const QUESTIONS = [

/* ===== 1. SPATENPROBE & BODENBEURTEILUNG ===== */
{c:'spaten',q:'Welches Kriterium gehoert NICHT zu den sechs Beurteilungspunkten einer Spatenprobe?',o:['Gefuegeform','Biologische Aktivitaet','Reifeninnendruck des Traktors','Verfaerbungen im Boden'],a:2,e:'Die sechs Kriterien sind: Befahr-/Bearbeitbarkeit, Bodenart, Gefuegeform, biologische Aktivitaet, Verfaerbungen und Schichten im Boden. Der Reifendruck wird am Fahrzeug geprueft, nicht am Erdblock.',s:'L9'},
{c:'spaten',q:'Wozu dient die Spatenprobe in erster Linie?',o:['Zur Bestimmung des Erntezeitpunkts','Um einen Einblick in den Boden zu erhalten und die geeignete Bodenbearbeitungsmassnahme zu bestimmen','Zur Messung des Reifendrucks','Zur Bestimmung der Saatmenge'],a:1,e:'Die Spatenprobe liefert Einblick in den Bodenaufbau und hilft, die passende Bearbeitungsmassnahme und -tiefe festzulegen.',s:'L9'},
{c:'spaten',q:'Was bedeutet eine blau-graue Verfaerbung im Bodenprofil?',o:['Hoher Humusgehalt','Vernaessung','Hoher Kalkgehalt','Gute Durchlueftung'],a:1,e:'Blau-graue Verfaerbungen zeigen Vernaessung an - dem Boden fehlt dauerhaft Sauerstoff.',s:'PPT'},
{c:'spaten',q:'Was deuten schwarze, verschmierte Punkte im Bodenprofil an?',o:['Bodenverdichtung','Regenwurmgaenge','Kalkanreicherung','Wurzelreste'],a:0,e:'Schwarze, verschmierte Punkte sind ein Zeichen fuer Bodenverdichtung.',s:'PPT'},
{c:'spaten',q:'Was zeigen Rostflecken im Boden an?',o:['Eisenmangel','Durchlueftungsschwankungen bzw. wechselnden Grundwasserspiegel','Zu hohen pH-Wert','Herbizidrueckstaende'],a:1,e:'Rostflecken entstehen durch wechselnde Durchlueftung, typischerweise bei schwankendem Grundwasserspiegel.',s:'PPT'},
{c:'spaten',q:'Wie soll der ausgestochene Erdblock bei der Spatenprobe geoeffnet werden?',o:['Mit dem Messer glatt durchschneiden','Von Hand entlang der natuerlichen Bruchstellen brechen','Mit dem Spaten zerschlagen','Mit Wasser aufloesen'],a:1,e:'Nur beim Brechen entlang natuerlicher Bruchstellen zeigt sich das echte Gefuege. Ein Schnitt wuerde das Bild verfaelschen.',s:'Unterricht'},
{c:'spaten',q:'Mit welchem Test laesst sich die Tragfaehigkeit des Bodens abschaetzen?',o:['Fuenflibertest','Schraubenziehertest','Salzsaeuretest','Fallprobe'],a:1,e:'Der Schraubenziehertest gibt Aufschluss ueber den Eindringwiderstand und damit ueber das Verdichtungsrisiko beim Befahren.',s:'Abs. 2.1.3'},
{c:'spaten',q:'Der Schraubenzieher laesst sich mit Daumen und Zeigefinger leicht in den Boden druecken. Was heisst das?',o:['Verdichtungsrisiko sehr hoch, nicht befahren','Boden ist optimal befahrbar','Boden ist zu trocken','Boden ist bearbeitbar'],a:0,e:'Geringer Kraftaufwand bedeutet sehr hohes Verdichtungsrisiko - der Boden ist zu feucht und darf nicht befahren werden.',s:'L4'},
{c:'spaten',q:'Der Schraubenzieher laesst sich nur mit dem Handballen eindruecken. Wie ist das Verdichtungsrisiko?',o:['Sehr hoch','Hoch','Gering, Boden ist befahrbar','Nicht beurteilbar'],a:2,e:'Hoher Kraftaufwand bedeutet geringes Verdichtungsrisiko - der Boden ist befahrbar.',s:'L4'},
{c:'spaten',q:'Der Schraubenzieher laesst sich mit der Faust eindruecken. Welche Konsequenz?',o:['Ohne Einschraenkung befahren','Nicht befahren oder Belastung reduzieren','Sofort pfluegen','Boden waessern'],a:1,e:'Mittlerer Kraftaufwand bedeutet hohes Verdichtungsrisiko: nicht befahren oder zumindest die Belastung reduzieren.',s:'L4'},
{c:'spaten',q:'Bis in welche Tiefe wird der Schraubenzieher beim Test in den Boden gedrueckt?',o:['2 cm','10 cm','25 cm','50 cm'],a:1,e:'Ein Schraubenzieher Nr. 4 wird bis in zehn Zentimeter Tiefe gedrueckt.',s:'Abs. 2.1.3'},
{c:'spaten',q:'Fuehlprobe "hart": Erdbrocken lassen sich nur mit Muehe auseinanderbrechen. Wie ist der Boden zu beurteilen?',o:['Befahrbar und bearbeitbar','Befahrbar, aber nicht bearbeitbar','Nicht befahrbar, aber bearbeitbar','Weder befahrbar noch bearbeitbar'],a:1,e:'Harter Boden traegt zwar, laesst sich aber nicht sinnvoll bearbeiten - die Kruemel wuerden zertruemmert.',s:'L5'},
{c:'spaten',q:'Fuehlprobe "bruechig": Erdbrocken zerbroeseln zwischen den Fingern. Wie ist der Boden zu beurteilen?',o:['Befahrbar und bearbeitbar','Befahrbar, aber nicht bearbeitbar','Nicht befahrbar, aber bearbeitbar','Weder befahrbar noch bearbeitbar'],a:0,e:'Bruechig ist der Idealzustand: der Boden ist sowohl befahrbar als auch bearbeitbar.',s:'L5'},
{c:'spaten',q:'Fuehlprobe "plastisch": Die Erde ist knetbar bis breiig. Wie ist der Boden zu beurteilen?',o:['Befahrbar und bearbeitbar','Befahrbar, aber nicht bearbeitbar','Nicht befahrbar, aber bearbeitbar','Weder befahrbar noch bearbeitbar'],a:3,e:'Plastischer Boden ist zu nass: weder befahren noch bearbeiten, sonst entstehen Verschmierung und Verdichtung.',s:'L5'},
{c:'spaten',q:'Warum dringt der Schraubenzieher in nassen Boden besonders leicht ein?',o:['Weil nasser Boden weniger Steine enthaelt','Weil die Feuchtigkeit wie ein Schmiermittel wirkt','Weil nasser Boden waermer ist','Weil sich der Ton verfestigt'],a:1,e:'Bei nassem Boden wirkt die Feuchtigkeit wie ein Schmiermittel - genau deshalb sind nasse Boeden stark verdichtungsgefaehrdet.',s:'Abs. 2.1.3'},
{c:'spaten',q:'Wo sollte man die Spatenprobe NICHT entnehmen?',o:['Mitten im Feld','In der Fahrgasse oder im Vorgewende','In einer normalen Bestandeslage','Auf durchschnittlichem Bodenniveau'],a:1,e:'Fahrgassen und Vorgewende sind untypisch stark verdichtet und liefern kein repraesentatives Bild.',s:'Unterricht'},
{c:'spaten',q:'Welches Werkzeug ergaenzt den Schraubenziehertest, um zusaetzlich die Bearbeitbarkeit zu beurteilen?',o:['Die Fuehlprobe','Der Fuenflibertest','Terranimo','Der Regenmesser'],a:0,e:'Mit der Fuehlprobe laesst sich nicht nur die Befahrbarkeit, sondern auch die Bearbeitbarkeit beurteilen.',s:'L5'},

/* ===== 2. BODENART, KOERNUNG & BESTANDTEILE ===== */
{c:'bodenart',q:'Was beschreibt die Bodenart?',o:['Den Humusgehalt des Bodens','Die Zusammensetzung aus Ton, Schluff und Sand','Die Anordnung der Hohlraeume','Den pH-Wert des Bodens'],a:1,e:'Die Bodenart beschreibt den Boden anhand seiner Zusammensetzung aus Ton, Schluff und Sand - z.B. sandiger Lehm.',s:'L-Begriffe / S.8'},
{c:'bodenart',q:'Welche Korngroesse hat Ton?',o:['kleiner als 0.002 mm','0.002 bis 0.05 mm','0.05 bis 2 mm','groesser als 2 mm'],a:0,e:'Tonteilchen sind kleiner als 0.002 mm - mikroskopisch kleine Gesteinsplaettchen.',s:'S.8'},
{c:'bodenart',q:'Welche Korngroesse hat Schluff?',o:['kleiner als 0.002 mm','0.002 bis 0.05 mm','0.05 bis 2 mm','2 bis 5 mm'],a:1,e:'Schluffteilchen liegen mit 0.002 bis 0.05 mm zwischen Ton und Sand.',s:'S.8'},
{c:'bodenart',q:'Welche Korngroesse hat Sand?',o:['kleiner als 0.002 mm','0.002 bis 0.05 mm','0.05 bis 2 mm','2 bis 20 mm'],a:2,e:'Sand umfasst Korngroessen von 0.05 bis 2 mm.',s:'S.8'},
{c:'bodenart',q:'Welche Eigenschaft von Ton ist ERWUENSCHT?',o:['Trocknet langsam ab','Verschmiert leicht','Speichert Naehrstoffe','Neigt zu Staunaesse'],a:2,e:'Ton speichert Wasser und Naehrstoffe und schuetzt vor Erosion. Langsames Abtrocknen und Verschmieren sind die Nachteile.',s:'L11 / S.9'},
{c:'bodenart',q:'Welche Eigenschaft von Sand ist UNERWUENSCHT?',o:['Erwaermt sich rasch','Trocknet rasch ab','Macht den Boden leicht bearbeitbar','Kann Wasser und Naehrstoffe nicht speichern'],a:3,e:'Sand kann weder Wasser noch Naehrstoffe speichern - das ist sein Hauptnachteil.',s:'L11 / S.9'},
{c:'bodenart',q:'Welche Eigenschaft ist typisch fuer Schluff?',o:['Speichert Naehrstoffe besonders gut','Verschlaemmt und erodiert leicht','Erwaermt sich sehr rasch','Ist besonders leicht zu bearbeiten'],a:1,e:'Schluff verschlaemmt und erodiert leicht und trocknet langsam ab. Er speichert zwar Wasser, aber kaum Naehrstoffe.',s:'L11 / S.9'},
{c:'bodenart',q:'Welcher Tonanteil kennzeichnet einen leichten Boden?',o:['unter 15 %','15 bis 30 %','30 bis 50 %','ueber 50 %'],a:0,e:'Leichte Boeden haben weniger als 15 % Ton.',s:'L10 / L51'},
{c:'bodenart',q:'Welcher Tonanteil kennzeichnet einen mittelschweren Boden?',o:['unter 10 %','15 bis 30 %','30 bis 45 %','ueber 50 %'],a:1,e:'Mittelschwere Boeden haben 15 bis 30 % Ton.',s:'L10 / L51'},
{c:'bodenart',q:'Ab welchem Tonanteil gilt ein Boden als schwer?',o:['ueber 10 %','ueber 20 %','ueber 30 %','ueber 60 %'],a:2,e:'Schwere Boeden haben mehr als 30 % Ton.',s:'L10 / L51'},
{c:'bodenart',q:'Ab welchem Anteil spricht man von einem Schluffboden?',o:['ab 20 % Schluff','ab 30 % Schluff','ab 50 % Schluff','ab 70 % Schluff'],a:2,e:'Ab 50 % Schluff spricht man von einem Schluffboden - er passt nicht in die Ton-Einteilung, weil der Schluff die Eigenschaften staerker praegt.',s:'L51b'},
{c:'bodenart',q:'Welche Bodenarten gehoeren zu den schweren Boeden?',o:['Sandboden und lehmiger Sandboden','Lehmboden und sandiger Lehmboden','Tonboden, lehmiger Tonboden, toniger Lehmboden','Schluffboden und Sandboden'],a:2,e:'Tonboden, lehmiger Tonboden und toniger Lehmboden haben ueber 30 % Ton und gelten als schwer.',s:'L51a'},
{c:'bodenart',q:'Welche Bodenarten gehoeren zu den leichten Boeden?',o:['Lehmiger Sandboden und Sandboden','Lehmboden und Tonboden','Toniger Lehm und Schluff','Sandiger Lehm und Lehm'],a:0,e:'Lehmiger Sandboden und Sandboden haben unter 15 % Ton und gelten als leicht.',s:'L51a'},
{c:'bodenart',q:'Welcher Bodentyp vereint die positiven Eigenschaften von Sand- und Tonboeden?',o:['Schluffboden','Lehmboden','Moorboden','Tonboden'],a:1,e:'Der Lehmboden enthaelt bedeutende Anteile aller drei Korngroessen und vereint dadurch die Vorteile.',s:'L12 / S.11'},
{c:'bodenart',q:'Warum wird ein tonreicher Boden als "schwer" bezeichnet?',o:['Weil er mehr wiegt pro Kubikmeter','Wegen des hohen Kraftaufwands bei der Bearbeitung','Weil er mehr Wasser enthaelt','Weil er tiefer liegt'],a:1,e:'Die Bezeichnung "schwer" bezieht sich auf den hohen Kraftaufwand, der fuer die Bearbeitung geleistet werden muss.',s:'S.8'},
{c:'bodenart',q:'Welcher Boden ist nach Niederschlag rascher wieder befahrbar?',o:['Tonboden','Sandiger Boden','Schluffboden','Lehmiger Ton'],a:1,e:'Sandige Boeden sind nach Niederschlag deutlich rascher befahrbar als Tonboeden, die nur ein kurzes Zeitfenster bieten.',s:'S.10'},
{c:'bodenart',q:'Was versteht man unter einem "Stundenboden"?',o:['Einen Boden, der nur eine Stunde pro Tag Sonne hat','Eine Flaeche, die nur waehrend eines sehr kurzen Zeitfensters bearbeitbar ist','Einen Boden, der in einer Stunde bearbeitet werden kann','Einen Boden mit stuendlich wechselndem pH-Wert'],a:1,e:'Mit zunehmendem Ton- und Schluffgehalt wird das Bearbeitungsfenster immer kleiner - im Extremfall spricht man von Stundenboeden.',s:'Abs. 4.1.1'},
{c:'bodenart',q:'Welche Bodenbestandteile sind ANORGANISCH?',o:['Ernteruecksiaende und Mist','Sand, Ton und Schluff','Humus und Wurzeln','Bakterien und Pilze'],a:1,e:'Anorganische (mineralische) Bestandteile entstehen aus Gestein: Steine, Sand, Schluff, Ton.',s:'L-Begriffe'},
{c:'bodenart',q:'Welche Bodenbestandteile sind ORGANISCH?',o:['Sand und Ton','Steine und Kies','Aus pflanzlichem oder tierischem Material entstandene Bestandteile wie Erntereste und Mist','Wasser und Luft'],a:2,e:'Organische Bodenbestandteile entstehen aus pflanzlichem oder tierischem Material - Erntereste, Mist, Wurzeln, Humus.',s:'L-Begriffe'},
{c:'bodenart',q:'Woraus besteht Boden? Welche vier Hauptgruppen?',o:['Nur Sand, Ton, Schluff und Steine','Mineralische Bestandteile, organische Bestandteile, Bodenlebewesen und Hohlraeume','Wasser, Luft, Duenger und Saatgut','Oberboden, Unterboden, Gestein und Grundwasser'],a:1,e:'Boden besteht aus mineralischen Bestandteilen, organischen Bestandteilen, Bodenlebewesen und Hohlraeumen (mit Luft und Wasser gefuellt).',s:'L1'},
{c:'bodenart',q:'Wie hoch ist der Anteil an Hohlraeumen in einem typischen Schweizer Boden?',o:['etwa 10 %','etwa 25 %','etwa 50 %','etwa 80 %'],a:2,e:'Die meisten Schweizer Boeden bestehen zur einen Haelfte aus Feststoffen und zur anderen Haelfte aus Hohlraeumen mit Wasser und Luft.',s:'Abs. 1.1'},
{c:'bodenart',q:'Welcher Bodenbestandteil laesst sich durch die Bewirtschaftung beeinflussen?',o:['Der Tonanteil','Der Sandanteil','Der Humusgehalt','Der Schluffanteil'],a:2,e:'Die mineralischen Bodenbestandteile sind von Natur aus gegeben. Nur der Humusgehalt laesst sich beeinflussen.',s:'S.8'},
{c:'bodenart',q:'Wie tief ist der Oberboden ueblicherweise?',o:['5 bis 10 cm','20 bis 30 cm','50 bis 60 cm','ueber 100 cm'],a:1,e:'Der Oberboden umfasst die obersten 20 bis 30 cm - dunkler gefaerbt, humusreich, viele Bodenlebewesen.',s:'L-Begriffe'},
{c:'bodenart',q:'Welche Schicht ist der wichtigste Naehrstoffspeicher?',o:['Der Oberboden','Der Unterboden','Das Muttergestein','Das Grundwasser'],a:0,e:'Der Oberboden ist der Naehrstoffspeicher, weil der groesste Teil der Naehrstoffe aus dem Humus stammt und der Humusanteil in den obersten 30 cm am groessten ist.',s:'L50b'},
{c:'bodenart',q:'Welche Schicht ist der wichtigste Wasserspeicher?',o:['Der Oberboden','Der Unterboden','Die Streuschicht','Das Muttergestein'],a:1,e:'Der Unterboden hat ein grosses Volumen und enthaelt oft tonhaltige Schichten, die Wasser zurueckhalten.',s:'L50b'},
{c:'bodenart',q:'Warum ist der Unterboden besonders verdichtungsgefaehrdet?',o:['Weil er mehr Sand enthaelt','Weil die biologische Aktivitaet dort viel geringer ist und es an stabilen Kruemeln fehlt','Weil er trockener ist','Weil er weniger Ton enthaelt'],a:1,e:'Im Unterboden ist die biologische Aktivitaet gering, deshalb besteht das Gefuege dort aus wenig stabilen Kruemeln.',s:'Abs. 1.1'},
{c:'bodenart',q:'Wie heissen die drei Horizonte im Bodenprofil?',o:['Horizont A (Oberboden), B (Unterboden), C (Muttergestein)','Horizont 1, 2 und 3','Krume, Sohle und Basis','Deckschicht, Mittelschicht, Grundschicht'],a:0,e:'Horizont A ist der Oberboden, Horizont B der Unterboden, Horizont C das Muttergestein.',s:'L50a'},
{c:'bodenart',q:'Was passiert mit Tonteilchen bei Feuchtigkeit?',o:['Sie schrumpfen','Sie quellen auf','Sie loesen sich auf','Sie verhaerten sofort'],a:1,e:'Tonteilchen quellen mit Wasser auf und schrumpfen bei Trockenheit - das erzeugt die natuerlichen Bruchstellen.',s:'S.9'},
{c:'bodenart',q:'Wie verhaelt sich Ton im trockenen Zustand?',o:['Hart wie Stein','Klebrig und verformbar','Pulvrig wie Mehl','Krumelig und locker'],a:0,e:'Im trockenen Zustand ist Ton hart wie Stein, im nassen Zustand klebrig und verformbar.',s:'S.9'},
{c:'bodenart',q:'Warum sind Sandboeden weniger verdichtungsgefaehrdet als Tonboeden?',o:['Weil Sand leichter ist','Weil zwischen den groesseren Sandteilchen groessere Zwischenraeume entstehen, in die Luft eindringt und Wasser rasch versickert','Weil Sand mehr Humus enthaelt','Weil Sand mehr Naehrstoffe bindet'],a:1,e:'Sandteilchen sind groesser als Tonteilchen, dadurch entstehen groessere Zwischenraeume - Wasser versickert rasch, Luft dringt ein.',s:'S.9'},
{c:'bodenart',q:'Welche Bodenart neigt am staerksten zu Staunaesse?',o:['Sandboden','Lehmiger Sand','Viel Ton, wenig Sand','Reiner Kies'],a:2,e:'Tonreiche Boeden neigen zu Staunaesse, weil das Wasser schlecht versickert.',s:'L52'},
{c:'bodenart',q:'Welche Bodenart neigt am staerksten zur Austrocknung?',o:['Viel Ton, wenig Sand','Wenig Ton, viel Sand','Viel Schluff','Lehmiger Ton'],a:1,e:'Sandreiche Boeden trocknen rasch aus, weil sie kaum Wasser speichern koennen.',s:'L52'},

/* ===== 3. BODENGEFUEGE & BODENPOREN ===== */
{c:'gefuege',q:'Was versteht man unter dem Bodengefuege (Bodenstruktur)?',o:['Den Anteil an Sand, Schluff und Ton','Die Anordnung der festen Bodenteilchen und der dazwischenliegenden Hohlraeume','Die Menge an Humus im Oberboden','Die Tiefe des durchwurzelbaren Raums'],a:1,e:'Bodenteilchen verbinden sich untereinander, dazwischen liegen Poren. Diese Anordnung nennt man Gefuege oder Struktur.',s:'S.13 / Begriffe'},
{c:'gefuege',q:'Wofuer ist ein gutes Bodengefuege wichtig? (4 Punkte)',o:['Wurzelwachstum, Wasserhaushalt, Lufthaushalt, Lebensraum fuer Bodenlebewesen','Farbe, Geruch, Temperatur, Gewicht','Saatmenge, Duengung, Ernte, Lagerung','Nur fuer den Wasserhaushalt'],a:0,e:'Das Gefuege bestimmt Wurzelwachstum, Wasser- und Lufthaushalt sowie den Lebensraum der Bodenlebewesen.',s:'S.13'},
{c:'gefuege',q:'Was sind Bodenkruemel?',o:['Kleine Steine im Oberboden','Von Auge knapp sichtbare Kluempchen aus organischem und anorganischem Material','Reine Tonplaettchen','Unverrottete Erntereste'],a:1,e:'Kruemel sind die kleinste funktionelle Einheit des Bodens - Verbindungen aus organischen und mineralischen Substanzen.',s:'L-Begriffe'},
{c:'gefuege',q:'Wie gross sind feine Bodenkruemel typischerweise?',o:['0.1 bis 0.5 mm','2 bis 5 mm','1 bis 2 cm','5 bis 10 cm'],a:1,e:'Feine Kruemel sind 2 bis 5 mm gross und rundlich; groebere Einheiten heissen Broeckel.',s:'Abs. 1.1'},
{c:'gefuege',q:'Wodurch werden Bodenkruemel zusammengehalten?',o:['Durch Frost','Durch Pilzfaeden sowie Wurzel- und Bakterienausscheidungen','Durch den Pflug','Durch Sandkoerner'],a:1,e:'Bodenlebewesen bilden die Kruemel; Pilzfaeden, Wurzel- und Bakterienausscheidungen wirken wie Klebstoff.',s:'Abs. 1.1'},
{c:'gefuege',q:'Welche Gefuegeform ist die erwuenschte?',o:['Polyeder','Kruemel','Klumpen','Einzelkorn'],a:1,e:'Das Kruemelgefuege ist das Ziel - es bietet der Pflanze alles, was sie braucht.',s:'S.13-14'},
{c:'gefuege',q:'Wie wird das Gefuege im Feld getestet?',o:['Erdziegel aus Huefthoehe fallen lassen','Salzsaeure auftroepfeln','Schraubenzieher eindruecken','Boden zwischen den Fingern reiben'],a:0,e:'Zerspringt der feuchte Erdziegel in Kruemel, ist das Gefuege gut. Grosse Polyeder deuten auf fehlerhafte Bewirtschaftung hin.',s:'PPT'},
{c:'gefuege',q:'Was bedeutet es, wenn beim Fallenlassen grosse kantige Polyeder zum Vorschein kommen?',o:['Optimales Gefuege','Hinweis auf fehlerhafte Bewirtschaftung','Hoher Humusgehalt','Zu viel Kalk'],a:1,e:'Kantige Polyeder sind ein Warnsignal fuer Bearbeitungs- oder Befahrungsfehler.',s:'PPT'},
{c:'gefuege',q:'Womit lassen sich Bodenkruemel bildlich vergleichen?',o:['Mit einem Haufen Tennisbaelle','Mit einer Ziegelmauer','Mit einem Schwamm','Mit Sandkoernern in einem Glas'],a:0,e:'Kruemel federn wie Tennisbaelle: Nach Belastung nehmen sie wieder ihre Form an. Mit einem Bulldozer ueberfahren waeren sie zerstoert.',s:'Abs. 2.1.1'},
{c:'gefuege',q:'Welche Porenart ist fuer Durchlueftung und rasche Wasserversickerung zustaendig?',o:['Feinporen','Mittelporen','Grobporen','Kapillarporen'],a:2,e:'Grobporen liegen zwischen Kruemeln, Sandteilchen und Regenwurmgaengen - dort versickert das Wasser.',s:'L13'},
{c:'gefuege',q:'In welchen Poren wird das pflanzenverfuegbare Wasser gespeichert?',o:['Grobporen','Mittelporen','Feinporen','In allen gleichmaessig'],a:1,e:'Mittelporen liegen im Innern von Kruemeln und zwischen Schluffteilchen - sie speichern das pflanzenverfuegbare Wasser.',s:'L13'},
{c:'gefuege',q:'Wo befinden sich die Feinporen?',o:['Zwischen Sandteilchen','Zwischen Ton-Plaettchen','In Regenwurmgaengen','An der Bodenoberflaeche'],a:1,e:'Feinporen liegen zwischen den Ton-Plaettchen und speichern nicht pflanzenverfuegbares Wasser (Totwasser).',s:'L13'},
{c:'gefuege',q:'Wie wird das Wasser in den Feinporen genannt?',o:['Sickerwasser','Kapillarwasser','Totwasser','Haftwasser'],a:2,e:'Totwasser ist zu stark gebunden, um von Pflanzen aufgenommen werden zu koennen.',s:'S.14'},
{c:'gefuege',q:'Was passiert bei einer Bodenverdichtung?',o:['Hohlraeume werden zusammengepresst und verkleinert','Der Humusgehalt steigt','Der pH-Wert steigt','Die Bodenart veraendert sich'],a:0,e:'Bei Verdichtung nehmen Luft und Wasser ab, feste Bestandteile zu. Das Bodenvolumen sinkt, die Dichte steigt.',s:'Abs. 2'},
{c:'gefuege',q:'Was ist der kapillare Wasseraufstieg?',o:['Das Versickern von Regen in die Tiefe','Das Aufsteigen von Wasser aus tieferen Schichten in den Oberboden durch feine Poren','Die Verdunstung an der Oberflaeche','Der Wassertransport in den Pflanzenwurzeln'],a:1,e:'In einem intakten Boden sind die Poren so fein, dass Wasser durch Kapillarkraft aus der Tiefe aufsteigen kann.',s:'L-Begriffe'},
{c:'gefuege',q:'Je duenner die Pore im Boden...',o:['...desto tiefer sinkt das Wasser','...desto hoeher steigt die Fluessigkeit','...desto weniger Wasser wird gespeichert','...desto schneller trocknet der Boden'],a:1,e:'Je duenner der Porendurchmesser, desto hoeher der Wasseraufstieg - ein rein physikalischer Prozess.',s:'Abs. 3'},
{c:'gefuege',q:'Wann wird die Kapillaritaet zum Nachteil?',o:['Wenn sie Pflanzen bei Trockenheit versorgt','Wenn Wasser bis an die Oberflaeche steigt und dort verdunstet','Wenn sie Naehrstoffe bindet','Wenn sie Wurzeln behindert'],a:1,e:'Steigt Wasser bis an die Oberflaeche und verdunstet dort, geht es verloren - deshalb unterbricht die Stoppelbearbeitung die Kapillaren.',s:'PPT'},
{c:'gefuege',q:'Warum trocknen Boeden nach dem Pfluegen schneller aus als nach flacher Bearbeitung?',o:['Weil mehr Sonne eindringt','Weil der Pflug die Kapillaren zerstoert und kein Wasser mehr aus der Tiefe aufsteigen kann','Weil der Boden dunkler wird','Weil mehr Wind eindringt'],a:1,e:'Durch den Pflug werden die Kapillaren zerstoert - der kapillare Wasseraufstieg aus tieferen Schichten faellt weg.',s:'L14 / S.14'},
{c:'gefuege',q:'Welche drei Wege des natuerlichen Gefuegeaufbaus gibt es?',o:['Biologisch, chemisch, physikalisch','Mechanisch, thermisch, elektrisch','Pfluegen, Grubbern, Eggen','Saeen, Duengen, Ernten'],a:0,e:'Biologisch durch Bodenlebewesen, chemisch ueber Ton-Humus-Komplexe, physikalisch durch Frost sowie Quellen und Schrumpfen.',s:'S.16-17'},
{c:'gefuege',q:'Welche Massnahme unterstuetzt den Gefuegeaufbau NICHT?',o:['Kunstwiese ansaeen','Gruenduengung','Ernterueckstaende einarbeiten','Moeglichst haeufig mit der Bodenfraese arbeiten'],a:3,e:'Die Bodenfraese zertruemmert den Boden intensiv und schaedigt das Gefuege - sie baut es nicht auf.',s:'S.16-17'},
{c:'gefuege',q:'Wer schafft laut Merksatz ein stabiles Bodengefuege?',o:['Der Pflug','Die Bodenlebewesen','Die Walze','Die Kreiselegge'],a:1,e:'"Ein stabiles Gefuege wird nicht von Maschinen, sondern von den Bodenlebewesen geschaffen."',s:'PPT'},
{c:'gefuege',q:'Was ist das Ziel beim Verhaeltnis von Gefuegeaufbau und Gefuegeabbau?',o:['Der Abbau soll ueberwiegen','Ein Gleichgewicht - der Strukturschwund darf nicht staerker sein als der Aufbau','Es spielt keine Rolle','Der Aufbau soll komplett wegfallen'],a:1,e:'Ziel ist, dass die schaedigenden Einfluesse der Bearbeitung nicht staerker sind als der Gefuegeaufbau durch Wurzeln und Bodenlebewesen.',s:'S.17'},
{c:'gefuege',q:'Was bedeutet Rueckverfestigung?',o:['Das Lockern des Bodens mit dem Grubber','Das Andruecken des Bodens mit Walze oder Packer, um grosse Hohlraeume zu eliminieren und Bodenschluss herzustellen','Das Wenden des Bodens mit dem Pflug','Das Aufbringen von Kalk'],a:1,e:'Rueckverfestigung stellt den Bodenschluss her und ermoeglicht den kapillaren Wasseraufstieg.',s:'L-Begriffe'},
{c:'gefuege',q:'Warum ist nach einer tiefen Lockerung eine Rueckverfestigung sinnvoll?',o:['Weil der Boden sonst zu trocken wird','Weil tief gelockerter Boden stark verdichtungsgefaehrdet ist','Weil sonst kein Unkraut keimt','Weil sonst der pH-Wert sinkt'],a:1,e:'Gelockerte Boeden sind sehr verdichtungsanfaellig - die Rueckverfestigung erhoeht die Tragfaehigkeit wieder.',s:'S.17 / L43'},
{c:'gefuege',q:'Was ist der Bodenschluss?',o:['Der Abschluss der Bodenbearbeitung','Der Kontakt von feuchtem Boden mit dem Saatgut','Das Verschliessen von Fahrspuren','Die oberste Bodenschicht'],a:1,e:'Bodenschluss ist der Kontakt zwischen feuchtem Boden und Saatgut - entscheidend fuer die Keimung.',s:'L-Begriffe'},
{c:'gefuege',q:'Warum ist frisch bearbeiteter Boden verdichtungsanfaelliger als bewachsener Boden?',o:['Weil er feuchter ist','Weil die Kruemel aus ihrem Verband geloest wurden','Weil er waermer ist','Weil er weniger Ton enthaelt'],a:1,e:'Das Loesen der Kruemel aus ihrem Verband laesst die Anfaelligkeit auf Verdichtung stark ansteigen. Gut durchwurzelte Boeden sind deutlich tragfaehiger.',s:'Abs. 2.1.1'},

/* ===== 4. TON-HUMUS-KOMPLEX & KALK ===== */
{c:'kalk',q:'Welches Ion verbindet Ton- und Humusteilchen zum Ton-Humus-Komplex?',o:['Kalium (K+)','Kalzium (Ca2+)','Nitrat (NO3-)','Ammonium (NH4+)'],a:1,e:'Kalzium ist zweifach positiv geladen und verbindet damit die negativ geladenen Ton- und Humusteilchen.',s:'S.13,15'},
{c:'kalk',q:'Welche Wirkung haben Ton-Humus-Komplexe NICHT?',o:['Foerdern die Kruemelbildung','Verbessern die Wasserversickerung','Erhoehen den Sandanteil im Boden','Reduzieren das Verdichtungsrisiko'],a:2,e:'Der Sandanteil gehoert zur fixen Bodenart und wird durch Ton-Humus-Komplexe nicht veraendert.',s:'S.13,15'},
{c:'kalk',q:'Welche vier Vorteile bringen Ton-Humus-Komplexe?',o:['Erhoehte Durchlueftung, hoehere Tragfaehigkeit, schnellere Wasserversickerung, leichteres Wurzeleindringen','Mehr Ton, mehr Sand, mehr Schluff, mehr Steine','Hoehere Ertraege, weniger Arbeit, tiefere Kosten, mehr Zeit','Mehr Wasser, mehr Waerme, mehr Licht, mehr Luft'],a:0,e:'Dazu kommt ein geringerer Zugkraftbedarf bei der Bearbeitung.',s:'S.19'},
{c:'kalk',q:'Welche positiven Eigenschaften hat eine Kalkgabe in einem sauren Boden?',o:['Sie senkt den pH-Wert weiter','Bessere Lebensbedingungen fuer Bodenlebewesen und bessere Naehrstoffverfuegbarkeit','Sie erhoeht den Tonanteil','Sie verhindert Regenwurmgaenge'],a:1,e:'Kalk verbessert die Lebensbedingungen, macht Naehrstoffe verfuegbarer, liefert Kalzium als Pflanzennaehrstoff und foerdert die Bodenstruktur ueber die Ton-Humus-Bruecke.',s:'L15'},
{c:'kalk',q:'Woher stammt Ricokalk?',o:['Nebenprodukt der Zuckergewinnung','Gemahlener Kalkstein','Nebenprodukt der AKW-Kuehlung','Aus Komposthaufen'],a:0,e:'Ricokalk faellt bei der Zuckerproduktion an.',s:'PPT'},
{c:'kalk',q:'Woher stammt Aarkalk?',o:['Aus der Zuckerfabrik','Nebenprodukt der AKW-Kuehlung an der Aare','Aus Kalksteinbruechen','Aus Klaerschlamm'],a:1,e:'Aarkalk faellt als Nebenprodukt bei der Kuehlung eines Kernkraftwerks an der Aare an.',s:'PPT'},
{c:'kalk',q:'Was ist Agrokalk?',o:['Nebenprodukt der Zuckergewinnung','Gemahlener Kalkstein - die teuerste Variante','Gebrannter Kalk','Ein fluessiger Blattduenger'],a:1,e:'Agrokalk ist gemahlener Kalkstein und unter den Kalkformen am teuersten.',s:'PPT'},
{c:'kalk',q:'Welche Besonderheit hat Branntkalk?',o:['Er ist am guenstigsten','Er wird mit Wasser sehr heiss, veraetzt Schnecken und bekaempft bodenbuertige Krankheiten','Er ist ein Zuckerfabrik-Nebenprodukt','Er wirkt versauernd'],a:1,e:'Branntkalk reagiert mit Wasser stark exotherm - wirksam gegen Schnecken und Krankheiten, dafuer teuer.',s:'PPT'},
{c:'kalk',q:'Welche Kalkform darf seit 2021 nicht mehr eingesetzt werden?',o:['Agrokalk','Ricokalk','KiWeCa','Branntkalk'],a:2,e:'KiWeCa ist seit 2021 verboten.',s:'PPT'},
{c:'kalk',q:'Wie laesst sich der Kalkgehalt im Feld einfach pruefen?',o:['Mit verduennter Salzsaeure - schaeumt es stark, ist viel Kalk vorhanden','Mit dem Schraubenziehertest','Mit dem Fuenflibertest','Durch Wiegen einer Bodenprobe'],a:0,e:'Starkes Aufschaeumen bedeutet viel Kalk (pH ueber 7), keine Reaktion bedeutet kalkfrei (pH unter 6.5).',s:'Buch'},
{c:'kalk',q:'Was gibt der pH-Wert an?',o:['Den Humusgehalt','Wie sauer oder alkalisch ein Boden ist','Die Bodenart','Die Wassermenge im Boden'],a:1,e:'Ein tiefer pH-Wert bedeutet sauer, ein hoher pH-Wert alkalisch.',s:'L-Begriffe'},
{c:'kalk',q:'Um welchen Faktor unterscheidet sich pH 3 von pH 6?',o:['Doppelt so sauer','10-mal so sauer','100-mal so sauer','1000-mal so sauer'],a:3,e:'Ein Punkt auf der pH-Skala entspricht dem Faktor 10, also 10x10x10 = 1000-mal so sauer.',s:'S.24'},
{c:'kalk',q:'Wodurch sinkt der pH-Wert im Boden?',o:['Durch Kalkgaben','Durch sauren Regen, Kalkauswaschung, saure Wurzelausscheidungen und saurewirkende Duenger','Durch Regenwuermer','Durch Gruenduengung'],a:1,e:'Diese vier Faktoren fuehren zur Bodenversauerung und machen Kalkgaben noetig.',s:'L15'},
{c:'kalk',q:'Wie sollte eine groessere Kalkung ausgefuehrt werden?',o:['Alles auf einmal','In mehreren Etappen, um starke pH-Schwankungen zu vermeiden','Nur im Winter','Nur bei nassem Boden'],a:1,e:'Starke Veraenderungen der pH-Verhaeltnisse sind zu vermeiden - deshalb Kalkung in mehreren Etappen.',s:'S.24'},
{c:'kalk',q:'Warum ist Kalzium auch direkt wichtig fuer die Pflanze?',o:['Es ist ein Pflanzenschutzmittel','Es ist ein wichtiger Pflanzennaehrstoff','Es ersetzt Stickstoff','Es faerbt die Blaetter gruen'],a:1,e:'Kalzium ist nicht nur Strukturbildner, sondern auch ein wichtiger Pflanzennaehrstoff.',s:'L15'},

/* ===== 5. HUMUS ===== */
{c:'humus',q:'Was ist Humus?',o:['Saemtliche abgestorbenen und teilweise zersetzten Lebewesen des Bodens','Nur frische Pflanzenreste an der Oberflaeche','Der mineralische Anteil des Bodens','Eine Bezeichnung fuer Kompost'],a:0,e:'Humus umfasst alle abgestorbenen und teilweise bereits zersetzten Lebewesen eines Bodens.',s:'Abs. 1.1'},
{c:'humus',q:'Was entsteht bei der Mineralisation?',o:['Huminstoffe','Mineralische Naehrstoffe','Ton-Humus-Komplexe','Bodenporen'],a:1,e:'Leicht abbaubares Material wird mineralisiert - dabei entstehen mineralische Naehrstoffe.',s:'L16'},
{c:'humus',q:'Was entsteht bei der Humifizierung?',o:['Mineralische Naehrstoffe','Humus','CO2 und Wasser','Nitrat'],a:1,e:'Schwer abbaubares Material wird humifiziert - dabei entsteht Humus.',s:'L16'},
{c:'humus',q:'Welche Eigenschaft hat Humus NICHT?',o:['Speichert Wasser und Naehrstoffe','Bindet Schadstoffe','Erhoeht den Tonanteil des Bodens','Speichert CO2 aus der Atmosphaere'],a:2,e:'Der Tonanteil gehoert zur fixen Bodenart und laesst sich nicht durch Humus veraendern.',s:'L17 / S.19'},
{c:'humus',q:'Warum erwaermt sich humusreicher Boden rascher?',o:['Weil Humus Waerme produziert','Wegen der dunklen Farbe, die Energie aufnimmt','Weil Humus weniger Wasser enthaelt','Weil Humus leichter ist'],a:1,e:'Dunkle Farbtoene nehmen Energie auf - humusreicher Boden erwaermt sich deshalb rascher.',s:'L17'},
{c:'humus',q:'Wie hoch sollte der Humusgehalt in einem leichten Ackerboden mindestens sein?',o:['Minimum 0.5 %','Minimum 2 %, besser 4 bis 6 %','Minimum 10 %','Minimum 20 %'],a:1,e:'In leichten bis mittelschweren Boeden sollte der Humusgehalt nicht unter 2 % fallen, besser sind 4 bis 6 %.',s:'L18'},
{c:'humus',q:'Ab welchem Humusgehalt gilt ein Boden als "humusarm"?',o:['unter 2 %','2 bis 5 %','5 bis 10 %','ueber 30 %'],a:0,e:'Unter 2 % Humus gilt ein Boden als humusarm.',s:'S.18'},
{c:'humus',q:'Wie wird ein Boden mit 5 bis 10 % Humus bezeichnet?',o:['Humusarm','Schwach humos','Humos','Organisch'],a:2,e:'5 bis 10 % gilt als humos; 2-5 % schwach humos, 10-30 % humusreich, ueber 30 % organisch.',s:'S.18'},
{c:'humus',q:'Ab welchem Humusgehalt spricht man von einem organischen Boden (Moorboden)?',o:['ueber 10 %','ueber 20 %','ueber 30 %','ueber 50 %'],a:2,e:'Ueber 30 % Humus gilt ein Boden als organisch.',s:'S.18'},
{c:'humus',q:'Mit welchen Massnahmen laesst sich der Humusgehalt erhoehen?',o:['Haeufiger pfluegen','Reduzierte Bodenbearbeitung, Mist oder Kompost ausbringen, Ernterueckstaende liegen lassen, viel Kunstwiese und Gruenduengung','Mehr mineralisch duengen','Boden offen liegen lassen'],a:1,e:'Diese vier Massnahmen bauen Humus auf.',s:'L19 / S.20'},
{c:'humus',q:'Welche drei Gruende erklaeren den Einfluss der Bodenbearbeitung auf den Humusgehalt?',o:['Einmischen von organischem Material, erleichterter Humusabbau durch Zerkleinern, Sauerstoffeintrag stimuliert Bodenlebewesen','Erwaermung, Bewaesserung, Duengung','Pfluegen, Eggen, Walzen','Frost, Regen, Wind'],a:0,e:'Diese drei Effekte wirken gleichzeitig - unterm Strich ueberwiegt bei intensiver Bearbeitung der Abbau.',s:'S.20'},
{c:'humus',q:'Welche Geraete foerdern den Humusabbau am staerksten?',o:['Federzinkenegge und Walze','Zinkenrotor und Bodenfraese','Direktsaat-Schar','Stoppelhobel'],a:1,e:'Zinkenrotor und Bodenfraese zertruemmern den Boden am intensivsten und foerdern dadurch den Humusabbau.',s:'S.20'},
{c:'humus',q:'Welche Verfahren wirken dem Humusabbau entgegen?',o:['Haeufiges Pfluegen','Mulch- und insbesondere Direktsaat','Intensive Saatbettbereitung','Offenes Brachliegen'],a:1,e:'Konservierende Massnahmen wie Mulch- und Direktsaat wirken dem Humusabbau entgegen.',s:'S.20'},
{c:'humus',q:'Welche Kulturen wirken humuszehrend?',o:['Kunstwiese und Gruenland','Kulturen mit intensiver Bodenbearbeitung, wenig Rueckstaenden und schwacher Durchwurzelung','Getreide','Gruenduengung'],a:1,e:'Humuszehrend sind Kulturen wie Kartoffeln oder Rueben; Getreide und Gruenland hinterlassen ein grosses Wurzelwerk und wirken humusmehrend.',s:'S.20'},
{c:'humus',q:'Warum kann ein humusreicher Boden im Herbst zum Problem werden?',o:['Er wird zu hart','Durch Mineralisierung koennen hohe Stickstoffmengen freigesetzt werden - Gefahr der Nitratauswaschung','Er trocknet zu schnell aus','Er zieht Schaedlinge an'],a:1,e:'Bei feuchtem, noch warmem Herbstboden setzt die Mineralisierung viel Stickstoff frei - deshalb schreibt der OeLN teils eine Begruenung vor.',s:'S.20'},
{c:'humus',q:'Welchen Effekt hat mehr Humus in einem SANDboden?',o:['Der Sandanteil sinkt','Mehr Bodenlebewesen, kruemeligerer Boden, tieferes Erosionsrisiko und bessere Wasser-/Naehrstoffspeicherung','Der Boden wird schwerer zu bearbeiten','Der pH-Wert sinkt stark'],a:1,e:'Humus gleicht die Schwaechen des Sandbodens aus - vor allem bei Speicherfaehigkeit und Erosionsschutz.',s:'L53'},
{c:'humus',q:'Welchen Effekt hat mehr Humus in einem TONboden?',o:['Der Boden wird schwerer bearbeitbar','Kruemeligerer, leichter bearbeitbarer Boden, tieferes Verdichtungsrisiko und bessere Durchlueftung','Der Tonanteil steigt','Das Wasser bleibt noch laenger stehen'],a:1,e:'Durch bessere Kruemelstruktur und Regenwurmgaenge fliesst Wasser besser ab - weniger Staunaesse, bessere Durchlueftung.',s:'L53'},
{c:'humus',q:'Was passiert mit entwaesserten Torfboeden bei intensiver Bewirtschaftung?',o:['Sie werden fruchtbarer','Torfsackung: Schrumpfung, Setzung und Humusabbau lassen den Boden buchstaeblich verschwinden','Sie verkalken','Der Humusgehalt steigt'],a:1,e:'Im Grossen Moos hat die Bodenmaechtigkeit seit 1868 um bis zu 2.25 Meter abgenommen.',s:'S.20'},
{c:'humus',q:'Womit wird Humus im Buch bildlich verglichen?',o:['Mit dem Salz in der Suppe','Mit dem Motor eines Traktors','Mit einem Schwamm','Mit einem Dach'],a:0,e:'Es braucht nicht viel davon, aber wenn es fehlt, wird die Suppe ungeniessbar.',s:'S.18'},

/* ===== 6. BODENLEBEWESEN & REGENWURM ===== */
{c:'leben',q:'In welche zwei Hauptgruppen werden Bodenlebewesen eingeteilt?',o:['Nuetzlinge und Schaedlinge','Mikroorganismen und Bodentiere','Pflanzen und Tiere','Aerobier und Anaerobier'],a:1,e:'Mikroorganismen (Bakterien, Archaeen, Pilze, Algen, Einzeller) und Bodentiere (Asseln, Milben, Insekten, Nematoden, Regenwuermer).',s:'S.21-23'},
{c:'leben',q:'Welche Gruppe gehoert zu den Mikroorganismen?',o:['Regenwuermer','Milben','Algen','Nematoden'],a:2,e:'Algen zaehlen wie Bakterien, Archaeen, Pilze und Einzeller zu den Mikroorganismen.',s:'S.21-23'},
{c:'leben',q:'Was sind Mikroorganismen?',o:['Winzige Lebewesen, die nur aus einer oder wenigen Zellen bestehen','Alle Tiere unter 5 cm','Nur Bakterien','Wurzelteile im Boden'],a:0,e:'Mikroorganismen sind von Auge nicht sichtbar und bestehen aus einer oder wenigen Zellen.',s:'L-Begriffe'},
{c:'leben',q:'Welche Aufgabe haben Bodenlebewesen NICHT?',o:['Abbau und Mineralisierung','Kruemelbildung','Bestimmung der Bodenart','Abbau von Krankheitserregern'],a:2,e:'Die Bodenart ist von Natur aus gegeben. Bodenlebewesen sorgen fuer Abbau, Kruemelbildung, Durchlueftung, Wasserversickerung, Durchmischung sowie Abbau von Krankheitserregern und Schadstoffen.',s:'L20'},
{c:'leben',q:'Was machen nitrifizierende Bakterien?',o:['Sie wandeln Nitrat zu Luftstickstoff um','Sie wandeln Ammonium ueber Nitrit zu pflanzenverfuegbarem Nitrat um','Sie fixieren Luftstickstoff in Wurzelknoellchen','Sie bauen verholzte Reste ab'],a:1,e:'Nitrifizierende Bakterien brauchen dafuer Sauerstoff und einen pH-Wert zwischen 6 und 9.',s:'L21 / S.22'},
{c:'leben',q:'Wie foerdert man nitrifizierende Bakterien?',o:['Fuer genuegend Sauerstoff sorgen (z.B. Bodenlockerung) und aufkalken','Den Boden verdichten','Staunaesse erzeugen','Den pH-Wert senken'],a:0,e:'Sie brauchen Sauerstoff und einen pH-Wert zwischen 6 und 9.',s:'L21'},
{c:'leben',q:'Was machen denitrifizierende Bakterien?',o:['Sie wandeln Ammonium zu Nitrat um','Sie wandeln Nitrat zu Luftstickstoff oder gasfoermigen Stickoxiden um','Sie bauen Humus auf','Sie binden Schadstoffe'],a:1,e:'Das ist ein bedeutender Stickstoffverlust - sie sind deshalb unerwuenscht.',s:'S.22'},
{c:'leben',q:'Wie verhindert man, dass sich denitrifizierende Bakterien zu stark verbreiten?',o:['Mehr duengen','Keine Bodenverdichtung, keine Verschlaemmung, keine staunassen Flaechen bewirtschaften','Mehr pfluegen','Den pH-Wert senken'],a:1,e:'Denitrifikation laeuft unter anaeroben Bedingungen ab - also genau bei Verdichtung und Staunaesse.',s:'L22'},
{c:'leben',q:'Ab welcher Bodentemperatur laeuft die Denitrifikation besonders stark ab?',o:['ueber 0 Grad','ueber 10 Grad','ueber 25 Grad','ueber 40 Grad'],a:1,e:'Denitrifikation spielt sich besonders in staunassen, verdichteten Boeden bei ueber 10 Grad ab.',s:'S.22'},
{c:'leben',q:'Was machen Knoellchenbakterien?',o:['Sie bauen Stroh ab','Sie leben in Symbiose mit Leguminosen und wandeln Luftstickstoff in Ammonium um','Sie zerstoeren Wurzeln','Sie produzieren Kalk'],a:1,e:'Da sie mehr Stickstoff binden als sie brauchen, geben sie einen Teil an die Leguminose ab.',s:'L-Begriffe / S.22'},
{c:'leben',q:'Welche Pflanzen sind Leguminosen mit Knoellchenbakterien?',o:['Weizen, Gerste, Hafer','Klee, Bohnen, Erbsen, Soja, Lupinen, Wicken, Luzerne','Mais, Raps, Kartoffeln','Rueben, Sonnenblumen, Zwiebeln'],a:1,e:'Diverse Kleearten sowie Bohnen, Erbsen, Soja, Lupinen, Wicken und Luzerne.',s:'L23'},
{c:'leben',q:'Wie ernaehren sich saprophytische Pilze?',o:['Von lebenden Pflanzen','Von totem organischem Material','In Symbiose mit Wurzeln','Von Mineralstoffen'],a:1,e:'Saprophyten (Saprotrophe) ernaehren sich ausschliesslich von totem organischem Material.',s:'L-Begriffe'},
{c:'leben',q:'Wie ernaehren sich parasitische Pilze?',o:['Von totem Material','Von lebenden Pflanzen - sie verursachen Krankheiten','In Symbiose mit Wurzeln','Von Bakterien'],a:1,e:'Parasitische Bodenpilze verursachen zum Beispiel Kartoffelpocken oder Kohlhernie.',s:'L-Begriffe / S.22'},
{c:'leben',q:'Welchen Vorteil hat die Pflanze durch Mykorrhiza-Pilze?',o:['Sie vergroessern die Wurzeloberflaeche und verbessern die Wasser- und Naehrstoffaufnahme','Sie toeten Schaedlinge ab','Sie produzieren Stickstoff','Sie erhoehen den pH-Wert'],a:0,e:'Die Pflanze kann Wasser und Naehrstoffe auch dann aufnehmen, wenn diese schwierig verfuegbar sind - etwa bei Trockenheit.',s:'L1 Frage 4'},
{c:'leben',q:'Was ist die Gegenleistung der Pflanze an den Mykorrhiza-Pilz?',o:['Wasser','Zucker','Stickstoff','Sauerstoff'],a:1,e:'Die Pflanze liefert dem Pilz Zucker - eine echte Symbiose.',s:'L1 Frage 4'},
{c:'leben',q:'Welche weiteren Vorteile bringen Mykorrhiza-Pilze?',o:['Sie stabilisieren das Bodengefuege und erhoehen die Pflanzengesundheit','Sie erhoehen den Tonanteil','Sie senken den Humusgehalt','Sie bekaempfen Regenwuermer'],a:0,e:'Stabilisierung des Bodengefueges und hoehere Pflanzengesundheit.',s:'L24a'},
{c:'leben',q:'Wie foerdert man Mykorrhiza-Pilze im Boden?',o:['Intensive Bodenbearbeitung','Angemessene Duengergaben, Fruchtfolge mit Klee-Gras, Zwischen- und Winterbegruenung, reduzierte Bodenbearbeitung','Hohe Duengergaben','Haeufiges Pfluegen'],a:1,e:'Auch biologische bzw. extensive Bewirtschaftung foerdert Mykorrhiza-Pilze.',s:'L24b'},
{c:'leben',q:'Was ist eine Symbiose?',o:['Ein Schaedlingsbefall','Eine Lebensgemeinschaft, in der sich zwei Organismen gegenseitig unterstuetzen','Der Abbau von organischem Material','Die Vermehrung durch Teilung'],a:1,e:'Zwei Organismen unterstuetzen sich gegenseitig, zum Beispiel durch Austausch von Naehrstoffen und Assimilaten.',s:'L-Begriffe'},
{c:'leben',q:'Welcher pH-Bereich ist fuer die meisten Bodenlebewesen optimal?',o:['3.0 bis 4.5','6.3 bis 7.6','8.5 bis 10','unter 5'],a:1,e:'In zu sauren Boeden nimmt die Zahl der Bakterien und Regenwuermer stark ab, in alkalischen Boeden geht die Wirkung der Pilze zurueck.',s:'S.24'},
{c:'leben',q:'In welchem Temperaturbereich ist die biologische Aktivitaet am hoechsten?',o:['0 bis 10 Grad','20 bis 35 Grad','40 bis 50 Grad','unter 0 Grad'],a:1,e:'Bei zu grosser Hitze verringert sich die Aktivitaet wieder.',s:'S.24'},
{c:'leben',q:'Welche fuenf Wachstumsbedingungen brauchen Bodenlebewesen?',o:['Luftsauerstoff, Wasser, Nahrung, optimaler pH-Wert, Waerme','Licht, Wasser, Waerme, Duenger, Ruhe','Ton, Sand, Schluff, Humus, Kalk','Stickstoff, Phosphor, Kalium, Kalzium, Magnesium'],a:0,e:'Diese fuenf Faktoren lassen sich alle durch die Bewirtschaftung beeinflussen.',s:'L25 / S.24'},
{c:'leben',q:'Welche Massnahme verbessert die Sauerstoffversorgung der Bodenlebewesen?',o:['Boden verdichten','Keine Verschlaemmung und keine Verdichtung, mechanische Unkrautbekaempfung','Staunaesse zulassen','Schwere Maschinen einsetzen'],a:1,e:'Hacken bricht verschlaemmte Schichten auf und bringt Luft in den Boden.',s:'L25'},
{c:'leben',q:'Warum sind zu dicke Mulchschichten problematisch?',o:['Sie foerdern Erosion','Sie verzoegern das Aufwaermen des Bodens','Sie senken den pH-Wert','Sie toeten Regenwuermer'],a:1,e:'Dicke Schichten aus Pflanzenrueckstaenden verzoegern die Bodenerwaermung - ein Zielkonflikt mit dem Bodenschutz.',s:'L25 / S.24'},
{c:'leben',q:'Welche Funktion haben Regenwuermer beim Naehrstoffkreislauf?',o:['Sie fressen organisches Material - dabei entstehen Humus und pflanzenverfuegbare Naehrstoffe','Sie produzieren Stickstoff aus der Luft','Sie binden Kalk','Sie zersetzen Steine'],a:0,e:'Durch das Fressen von Mist, Kompost und Ernteresten entstehen Humus und pflanzenverfuegbare Naehrstoffe.',s:'L1 Frage 3'},
{c:'leben',q:'Welchen Nutzen haben Regenwurmgaenge?',o:['Sie lockern den Oberboden, bringen Luft hinein und lassen Regenwasser versickern','Sie speichern Naehrstoffe','Sie erhoehen den pH-Wert','Sie verhindern Wurzelwachstum'],a:0,e:'Wurzeln koennen in den Gaengen rasch in die Tiefe wachsen und die Wasserreserven im Unterboden nutzen.',s:'L1 Frage 3'},
{c:'leben',q:'Welche Rolle spielt der Schleim der Regenwuermer?',o:['Er wirkt wie Klebstoff und foerdert die Bildung von Bodenkruemeln','Er toetet Krankheitserreger','Er senkt den pH-Wert','Er speichert Wasser'],a:0,e:'Der Schleim wirkt wie Klebstoff und foerdert die Kruemelbildung, die den Boden vor Auswaschung und Erosion schuetzt.',s:'L1 Frage 3'},
{c:'leben',q:'Wie viel mehr Stickstoff enthaelt Regenwurmkot gegenueber der Umgebungserde?',o:['2-fach','5-fach','7-fach','10-fach'],a:1,e:'Stickstoff 5x, Phosphor 7x, Kalium 10x.',s:'S.25-26'},
{c:'leben',q:'Wie viel mehr Phosphor enthaelt Regenwurmkot gegenueber der Umgebungserde?',o:['2-fach','5-fach','7-fach','10-fach'],a:2,e:'Stickstoff 5x, Phosphor 7x, Kalium 10x.',s:'S.25-26'},
{c:'leben',q:'Wie viel mehr Kalium enthaelt Regenwurmkot gegenueber der Umgebungserde?',o:['2-fach','5-fach','7-fach','10-fach'],a:3,e:'Stickstoff 5x, Phosphor 7x, Kalium 10x.',s:'S.25-26'},
{c:'leben',q:'Wie sollte man bei der Bodenbearbeitung vorgehen, damit moeglichst wenige Wuermer zerstoert werden?',o:['Zapfwellengetriebene Geraete mit Winkelmesser einsetzen','Gezogene Geraete einsetzen, keine Winkelmesser, moeglichst auf den Pflug verzichten, bei grosser Hitze bearbeiten','Immer tief pfluegen','Nur bei Naesse arbeiten'],a:1,e:'Bei grosser Hitze zieht sich der Regenwurm in tiefere Schichten zurueck - deshalb sind die Verluste dann am geringsten.',s:'L26a'},
{c:'leben',q:'Welche zapfwellengetriebenen Geraete sind fuer Regenwuermer am schaedlichsten?',o:['Geraete mit Winkelmesser, z.B. die Bodenfraese','Die Federzinkenegge','Die Walze','Der Stoppelhobel'],a:0,e:'Bei zapfwellengetriebenen Geraeten sind solche mit Winkelmesser am schaedlichsten.',s:'S.25-26'},
{c:'leben',q:'Welchen Einfluss haben Herbizide auf Regenwuermer?',o:['Keinen','Der Algenrasen als Nahrungsquelle wird zerstoert, wodurch die Kruemelbildung eingeschraenkt wird','Sie toeten sie direkt ab','Sie foerdern ihre Vermehrung'],a:1,e:'Herbizide zerstoeren auch den Algenrasen, von dem sich die Regenwuermer ernaehren.',s:'L26c / S.26'},
{c:'leben',q:'Wie pflanzt sich der Regenwurm fort?',o:['Durch Teilung','Als Zwitter durch Austausch von Samenpaketen','Durch Sporen','Ungeschlechtlich durch Knospung'],a:1,e:'Regenwuermer sind Zwitter. Eine Vermehrung durch Teilung ist NICHT moeglich.',s:'S.25-26'},
{c:'leben',q:'Wie viele Regenwuermer leben typischerweise unter einem Quadratmeter Ackerland?',o:['10 bis 20','100 bis 200','200 bis 400','ueber 1000'],a:1,e:'Unter Ackerland sind es 100 bis 200, unter Weiden meist 200 bis 400.',s:'S.25-26'},
{c:'leben',q:'Welche drei Regenwurm-Typen werden unterschieden?',o:['Tiefgraeber, Flachgraeber, Streubewohner','Grosse, mittlere, kleine','Sommer-, Winter- und Ganzjahreswuermer','Rote, braune und graue'],a:0,e:'Tiefgraeber bauen ueber einen Meter tiefe senkrechte Gaenge, Flachgraeber bis 40 cm waagrecht, Streubewohner leben in den obersten fuenf Zentimetern.',s:'S.25-26'},
{c:'leben',q:'Welche Krankheitserreger baut der Regenwurm in seinem Verdauungstrakt ab?',o:['Nur Bakterien','Rhizoctonia und Fusarium','Nur Viren','Keine'],a:1,e:'Regenwuermer scheuen befallene Pflanzenreste nicht: Rhizoctonia (Kartoffeln, Rueben) und Fusarium (Getreide) werden abgebaut.',s:'S.25-26'},
{c:'leben',q:'Wie viel Getreidestroh koennen Regenwuermer pro Jahr zersetzen?',o:['bis 0.5 t/ha','bis 2 t/ha','bis 6 t/ha','bis 20 t/ha'],a:2,e:'Nach der Getreideernte kann innerhalb eines Jahres das ganze Getreidestroh (bis 6 t/ha) zersetzt werden.',s:'S.25-26'},
{c:'leben',q:'Welche Wirkungen haben Pflanzenwurzeln im Boden?',o:['Sie verhindern Erosion, entziehen Naehrstoffe, holen als Tiefwurzler Naehrstoffe aus dem Unterboden und geben Stoffe als Nahrung ab','Sie verdichten den Boden','Sie senken den Humusgehalt','Sie toeten Bodenlebewesen'],a:0,e:'Wurzeln "halten" den Boden fest, veraendern ueber Naehrstoffentzug den pH-Wert und ernaehren Bodenlebewesen.',s:'L1 Frage 5'},
{c:'leben',q:'Welche drei negativen Effekte hat das Fehlen von Regenwuermern?',o:['Fehlende Gaenge (weniger Luft, schlechtere Versickerung, langsameres Wurzelwachstum), langsamerer Abbau von Ernteresten, langsamere Kruemelneubildung','Hoeherer pH-Wert, mehr Kalk, mehr Ton','Mehr Humus, mehr Naehrstoffe, mehr Wasser','Weniger Unkraut, weniger Schaedlinge, weniger Krankheiten'],a:0,e:'Ohne Regenwuermer bleiben Krankheitserreger laenger aktiv und der Boden bleibt laenger erosionsanfaellig.',s:'L3'},

/* ===== 7. ERNTERUECKSTAENDE & PFLANZENBEWUCHS ===== */
{c:'ernte',q:'Welche drei Punkte sind bei der Einarbeitung von Ernterueckstaenden zu beruecksichtigen?',o:['Zustand (C/N-Verhaeltnis), Volumen und Groesse der Pflanzenreste','Farbe, Geruch und Gewicht','Preis, Verfuegbarkeit und Transport','Sorte, Saatzeit und Erntezeit'],a:0,e:'Diese drei Kriterien entscheiden ueber Verrottungsgeschwindigkeit und Geraetewahl.',s:'S.27'},
{c:'ernte',q:'Welche Erntereste verrotten am langsamsten?',o:['Kartoffelstauden','Ruebenlaub','Abgetrocknetes, kohlenstoffreiches Getreide- und Maisstroh','Frische Gruenduengung'],a:2,e:'Kohlenstoffreiche, trockene Reste verrotten langsam; stickstoffreiche Reste wie Kartoffelstauden oder Ruebenlaub mineralisieren rasch.',s:'S.27'},
{c:'ernte',q:'Wie laesst sich die Strohrotte beschleunigen?',o:['Stroh trocken liegen lassen','Eine Guellegabe auf das Stroh ausbringen','Stroh moeglichst lang lassen','Den Boden verdichten'],a:1,e:'Die Guellegabe gleicht das weite C/N-Verhaeltnis des Strohs aus und foerdert die Zersetzung.',s:'S.32'},
{c:'ernte',q:'Warum soll Stroh vom Maehdrescher gehaeckselt und gleichmaessig verteilt werden?',o:['Damit es schneller trocknet','Um die Angriffsflaeche fuer Bodenlebewesen zu vergroessern und den Abbau zu beschleunigen','Damit weniger Schnecken auftreten','Um Unkraut zu unterdruecken'],a:1,e:'Kurz gehaeckselte Reste haben eine grosse Oberflaeche und verrotten rascher. Strohmahden lassen sich spaeter kaum noch verteilen.',s:'Abs. 3 / S.27'},
{c:'ernte',q:'Welche positiven Eigenschaften haben Ernterueckstaende an der Bodenoberflaeche?',o:['Weniger Erosion und Verschlaemmung, Schutz vor Regentropfen, weniger Austrocknung, Schutz fuer Bodenlebewesen','Sie erhoehen den Tonanteil','Sie senken den pH-Wert','Sie foerdern Verdichtung'],a:0,e:'Eine Bedeckung von mindestens 30 % reduziert das Erosionsrisiko deutlich.',s:'L27a / S.27'},
{c:'ernte',q:'Ab welcher Bodenbedeckung mit Ernterueckstaenden sinkt das Erosionsrisiko deutlich?',o:['ab 10 %','ab 30 %','ab 60 %','ab 90 %'],a:1,e:'Eine Bodenoberflaeche, die zu mindestens 30 Prozent bedeckt ist, reduziert das Erosionsrisiko.',s:'S.27'},
{c:'ernte',q:'Warum sollten Ernterueckstaende nach Mais gut eingearbeitet oder untergepfluegt werden?',o:['Weil Mais den pH-Wert senkt','Weil der Maiszuensler sonst in den oberflaechlichen Maisstoppeln ueberwintert und Fusarien auf nachfolgenden Weizen uebertragen werden','Weil Maisstroh giftig ist','Weil sonst kein Wasser versickert'],a:1,e:'Maiszuensler ueberwintert in den Stoppeln; Fusarien wandern in den Folgeweizen.',s:'L27b'},
{c:'ernte',q:'Welches Geraet ist bei grossen Mengen Ernterueckstaenden NICHT geeignet, weil es zu wenig mischt?',o:['Grubber mit Meisselscharen','Scheibenegge','Kreiselegge','Spatenrollegge'],a:2,e:'Die Kreiselegge mischt ungenuegend. Ebenfalls ungeeignet sind gezogene Geraete mit vielen Zinken, weil sie rasch verstopfen.',s:'S.27'},
{c:'ernte',q:'Welche Geraete eignen sich zur flachen Einarbeitung von Ernterueckstaenden?',o:['Fluegelschargrubber oder Scheibenegge','Kreiselegge','Walze','Saemaschine'],a:0,e:'Bei geringer Bearbeitungstiefe eignen sich Fluegelschargrubber oder Scheibenegge; soll tiefer gelockert werden, ein Grubber mit Meisselscharen.',s:'S.27'},
{c:'ernte',q:'Was ist das Risiko beim Unterpfluegen grosser Mengen organischen Materials?',o:['Der pH-Wert steigt','Es entstehen "Matratzen", welche die Verrottung, das Wurzelwachstum und den kapillaren Wasseraufstieg behindern','Der Boden wird zu locker','Es entsteht zu viel Humus'],a:1,e:'Zu tiefes Einarbeiten behindert die Verrottung - typische Folge sind Strohmatratzen.',s:'S.31'},
{c:'ernte',q:'Was gilt als Faustregel bei viel und wenig zersetztem Pflanzenmaterial?',o:['Je mehr Reste, desto groesser die Geraeteauswahl','Je mehr Pflanzenreste und je weniger zersetzt, desto kleiner die Auswahl an geeigneten Maschinen','Die Geraetewahl spielt keine Rolle','Nur der Pflug funktioniert'],a:1,e:'Je mehr und je unzersetzter das Material, desto weniger Maschinen kommen in Frage.',s:'S.27'},
{c:'ernte',q:'Wie geht man vor, wenn viele Quecken oder Ackerwinden auf dem Feld sind?',o:['Scheibenegge einsetzen','Keine schneidenden Geraete verwenden, stattdessen flache, ganzflaechig durchschneidende Geraete - allenfalls vorher systemisches Herbizid','Mit der Bodenfraese arbeiten','Nichts unternehmen'],a:1,e:'Schneidende Geraete zerteilen die Wurzeln, aus jedem Stueck treibt eine neue Pflanze aus.',s:'L28a'},
{c:'ernte',q:'Was bedeutet vegetative Vermehrung?',o:['Vermehrung ueber Samen','Vermehrung ueber ober- oder unterirdische Auslaeufer und Wurzelteile, ohne Bluete und Befruchtung','Vermehrung durch Sporen','Vermehrung durch Pfropfung'],a:1,e:'Beispiele mit negativer Wirkung: Quecken, Blacken, Disteln, Erdmandelgras.',s:'S.28'},
{c:'ernte',q:'Welche Geraete werden zur Bekaempfung von Wurzelunkraeutern empfohlen?',o:['Scheibenegge und Kreiselegge','Stoppelhobel, Fluegelschargrubber oder Flachgrubber','Bodenfraese','Zinkenrotor'],a:1,e:'Flach arbeitende Geraete durchschneiden ganzflaechig, ohne die Wurzeln in vermehrungsfaehige Stuecke zu zerteilen.',s:'S.28'},
{c:'ernte',q:'Was kann eine unterschaetzte Ursache fuer starken Queckenbefall sein?',o:['Zu hoher Humusgehalt','Bodenverdichtung','Zu viele Regenwuermer','Zu hoher pH-Wert'],a:1,e:'Manchmal ist Bodenverdichtung die Hauptursache fuer das Ueberhandnehmen von Quecke oder Breitwegerich - dann gehoert Lockerung zur Bekaempfungsstrategie.',s:'S.28'},
{c:'ernte',q:'Was sind ausdauernde Unkraeuter?',o:['Unkraeuter, die im Winter absterben','Wurzelunkraeuter, die im Winter nicht absterben und nach der Winterruhe weiterwachsen','Nur einjaehrige Arten','Unkraeuter in Gewaechshaeusern'],a:1,e:'Beispiele sind Quecken, Blacken, Winden oder Ackerkratzdisteln - meist Problemunkraeuter.',s:'S.28'},
{c:'ernte',q:'Welcher Pflanzenbewuchs stellt die hoechsten Anspruechen an die Mechanisierung?',o:['Eine abgefrorene, weitgehend zersetzte Zwischenkultur','Wenig zersetzte, nasse Pflanzenrueckstaende oder lebende Klee-Gras-Mischungen','Ein kahler Acker','Kurz gehaeckseltes Stroh'],a:1,e:'Lebende oder wenig zersetzte Bestaende sind deutlich schwieriger einzuarbeiten als eine abgefrorene Zwischenkultur.',s:'S.28'},
{c:'ernte',q:'Welche Nebenwirkung hat eine gute Einarbeitung von Ernterueckstaenden?',o:['Weniger Pilzkrankheiten, weniger Maiszuensler und Schnecken, Unkrautbekaempfung','Mehr Erosion','Hoeherer Reifendruck noetig','Weniger Humus'],a:0,e:'Korrekt eingestellte Pfluege schaffen alle Rueckstaende unter die Oberflaeche und reduzieren die Uebertragung von Pilzkrankheiten.',s:'S.27'},

/* ===== 8. BEFAHRBARKEIT, VERDICHTUNG & RADLAST ===== */
{c:'befahren',q:'Was ist Bodendruck?',o:['Der Luftdruck im Reifen','Die Kraft, die von oben auf den Boden einwirkt','Das Gewicht des ganzen Traktors','Der Widerstand des Bodens'],a:1,e:'Ist der Bodendruck groesser als die Bodenfestigkeit, verdichtet sich der Boden. 1 bar entspricht 1 kg auf 1 cm2.',s:'Abs. 2'},
{c:'befahren',q:'Was ist die Radlast?',o:['Der Reifeninnendruck','Das Gewicht, das auf dem einzelnen Rad lastet','Das Gesamtgewicht des Traktors','Die Auflageflaeche des Reifens'],a:1,e:'Als Radlast wird die Gewichtskraft bezeichnet, mit der ein einzelnes Rad auf den Boden drueckt.',s:'L-Begriffe / Abs. 2.3.1'},
{c:'befahren',q:'Was ist die Hauptursache fuer UNTERBODENverdichtung?',o:['Eine zu kleine Auflageflaeche','Eine zu grosse Radlast','Zu hoher Humusgehalt','Zu trockener Boden'],a:1,e:'Zu hohe Radlasten bei nassem Boden sind die Hauptursache fuer Unterbodenverdichtungen.',s:'L31 / Abs. 2.3.1'},
{c:'befahren',q:'Was ist die Hauptursache fuer OBERBODENverdichtung?',o:['Eine zu grosse Radlast','Eine zu kleine Auflageflaeche der Raeder','Zu wenig Humus','Zu viel Kalk'],a:1,e:'Die Ursache fuer Verdichtungen im Oberboden ist oft eine zu kleine Auflageflaeche der Raeder.',s:'L31'},
{c:'befahren',q:'Ab welcher Radlast koennen auch breite Reifen den Bodendruck oft nicht mehr ausreichend verringern?',o:['ab 1 Tonne','ab 2 Tonnen','ab 3 Tonnen','ab 10 Tonnen'],a:2,e:'Bei Radlasten ueber drei Tonnen reichen auch breite Reifen oft nicht mehr aus.',s:'L31'},
{c:'befahren',q:'Was mindert das Verdichtungsrisiko?',o:['Geringe Radlasten, grosse Auflageflaechen und ein niedriger Reifeninnendruck','Hohe Radlasten und schmale Reifen','Hoher Reifendruck und schnelles Fahren','Nasser Boden und schwere Maschinen'],a:0,e:'Diese drei Faktoren wirken zusammen.',s:'L31'},
{c:'befahren',q:'Warum sind Unterbodenverdichtungen besonders schlimm?',o:['Sie sind sofort sichtbar','Sie bleiben ueber Jahrzehnte bestehen und fuehren zu Ertragsminderungen','Sie erhoehen den pH-Wert','Sie foerdern Unkraut'],a:1,e:'Maschinelle Lockerung in der Tiefe ist teuer, biologische Lockerung ist eingeschraenkt und Frost wirkt selten tiefer als 20 bis 25 cm.',s:'Abs. 2.3'},
{c:'befahren',q:'Wie tief wirkt die physikalische Lockerung durch Frost und Trockenheit?',o:['bis 5 cm','selten mehr als 20 bis 25 cm','bis 50 cm','bis 1 Meter'],a:1,e:'Deshalb lassen sich Unterbodenverdichtungen nicht einfach "aussitzen".',s:'Abs. 2.3'},
{c:'befahren',q:'Welche vier Faktoren bestimmen die Befahrbarkeit des Bodens?',o:['Bodenzustand, Bodenart, Radlast, Auflageflaechen','Temperatur, Wind, Regen, Sonne','Kultur, Sorte, Saatzeit, Duengung','Humus, Kalk, pH, Ton'],a:0,e:'Bodenzustand (Festigkeit und Feuchtigkeit), Bodenart, Radlast und Auflageflaechen der Fahrzeuge.',s:'Abs. 2.4'},
{c:'befahren',q:'Welche zwei Bodenschaeden entstehen beim Befahren oder Bearbeiten von nassem Boden?',o:['Erosion und Verschlaemmung','Verdichtung und Verschmierung','Austrocknung und Rissbildung','Versauerung und Auswaschung'],a:1,e:'Nasser Boden verdichtet und verschmiert - daraus entsteht unter anderem die Pflugsohle.',s:'L6'},
{c:'befahren',q:'Welches Problem entsteht NICHT direkt durch verdichtete Boeden?',o:['Weniger Bodenporen und schlechtere Luftversorgung der Wurzeln','Schlechte Durchwurzelbarkeit','Hoeherer Humusgehalt','Staunaesse mit Faeulnis'],a:2,e:'Verdichtung foerdert den Humusabbau nicht - sie fuehrt zu weniger Poren, schlechter Durchwurzelung, Austrocknungsrisiko und Staunaesse.',s:'L7'},
{c:'befahren',q:'In welchen Situationen im Jahresverlauf ist das Verdichtungsrisiko besonders hoch?',o:['Im Hochsommer bei Trockenheit','Pfluegen im fruehen Fruehjahr oder Spaetherbst, Guelle-/Mistausbringung, Maissilierung, spaete Zuckerruebenernte','Bei der Getreidesaat im September','Waehrend der Bluete'],a:1,e:'Frueh im Fruehjahr und spaet im Herbst ist der Boden oft nass und daher wenig tragfaehig.',s:'L8'},
{c:'befahren',q:'Welche Massnahme reduziert die Radlast NICHT?',o:['Leichte Traktoren und Maschinen einsetzen','Auf ueberfluessigen Ballast verzichten','Den Reifeninnendruck erhoehen','Tandem- oder Kurmannachsen verwenden'],a:2,e:'Ein hoeherer Reifendruck verkleinert die Auflageflaeche und verschlimmert das Problem.',s:'L32'},
{c:'befahren',q:'Welche Massnahme reduziert die Radlast beim Guellefuehren?',o:['Groesseres Guellefass waehlen','Guelle verschlauchen oder ein kleinvolumiges Guellefass waehlen','Schneller fahren','Reifendruck erhoehen'],a:1,e:'Gueolleverschlauchung statt Guellefass ist eine der wirksamsten Massnahmen zur Radlastreduktion.',s:'L32 / Abs. 2.3.1'},
{c:'befahren',q:'Welche drei Massnahmen vermeiden Bodenschaeden ausser der Radlastreduktion?',o:['Reifeninnendruck unter 1 bar senken, Breit-/Doppelbereifung, Arbeit abbrechen bei Fahrspuren oder Schlupf','Schneller fahren, tiefer arbeiten, mehr duengen','Mehr Kalk, mehr Humus, mehr Wasser','Nachts arbeiten, langsam fahren, oefter wenden'],a:0,e:'Diese drei greifen direkt beim Bodendruck an.',s:'L33'},
{c:'befahren',q:'Was ist Schlupf?',o:['Das kurzzeitige, oft unmerkliche Durchdrehen des Traktorrades auf der Bodenoberflaeche','Das Abrutschen am Hang','Der Unterschied zwischen Reifendruck und Bodendruck','Das Einsinken des Reifens'],a:0,e:'Schlupf ist der Unterschied zwischen theoretisch zurueckgelegtem und tatsaechlich gefahrenem Weg - die Kraefte zerstoeren die Bodenstruktur.',s:'L-Begriffe / Abs. 2.3.2'},
{c:'befahren',q:'Wie laesst sich Schlupf auf ein Minimum beschraenken?',o:['Er laesst sich ganz vermeiden','Durch sorgfaeltige Reifenwahl, angepasste Reifeninnendruecke und angepasste Fahrgeschwindigkeit','Durch hoeheren Reifendruck','Durch schnelleres Fahren'],a:1,e:'Schlupf kann nie ganz verhindert, aber deutlich reduziert werden.',s:'Abs. 2.3.2'},
{c:'befahren',q:'Was bewirkt das Absenken des Reifeninnendrucks?',o:['Kleinere Auflageflaeche','Der Reifen verformt sich staerker, die Auflageflaeche wird groesser, Bodendruck und Schlupf sinken','Hoehere Geschwindigkeit','Mehr Verdichtung'],a:1,e:'Bei der Bodenbearbeitung soll sich in erster Linie der Reifen verformen und nicht der Boden.',s:'Abs. 2.3.2'},
{c:'befahren',q:'Welcher Reifeninnendruck gilt als Faustregel im Feld (Standardbereifung)?',o:['0.2 bis 0.4 bar','0.8 bis 1 bar','1.6 bis 2 bar','ueber 2.5 bar'],a:1,e:'Im Feld 0.8 bis 1 bar, auf der Strasse circa 1.6 bar fuer die Strassensicherheit.',s:'Abs. 2.3.2'},
{c:'befahren',q:'Welche Faustregel gilt fuer den Zusammenhang Reifeninnendruck und Bodendruck?',o:['Reifeninnendruck minus 0.4 bar','Reifeninnendruck plus 0.4 bar entspricht etwa dem Druck auf den Boden','Reifeninnendruck mal 2','Beide sind immer gleich'],a:1,e:'Reifeninnendruck + 0.4 bar entspricht in etwa dem Druck auf den Boden.',s:'Abs. 2.3.2'},
{c:'befahren',q:'Welcher Bodendruck sollte im Ackerbau mit Pflugeinsatz auf 20 cm Tiefe nicht ueberschritten werden?',o:['0.5 bar','1 bar','2 bar','3 bar'],a:1,e:'Nicht mehr als 1 bar Bodendruck auf 20 Zentimetern Tiefe.',s:'Abs. 2.3.2'},
{c:'befahren',q:'Ab welchem Reifeninnendruck koennen moderne VF-Reifen eingesetzt werden?',o:['ab 0.4 bar','ab 0.8 bar','ab 1.2 bar','ab 1.6 bar'],a:0,e:'Moderne Spezialreifen der VF-Technologie kommen bereits ab 0.4 bar aus.',s:'Abs. 2.3.2 / 4.1.3'},
{c:'befahren',q:'Ab welcher Radlast sollte ein Reifendruck-Regulierungssystem in Erwaegung gezogen werden?',o:['ab 0.5 bis 1 Tonne','ab 3 bis 4 Tonnen','ab 8 Tonnen','ab 15 Tonnen'],a:1,e:'Besonders wichtig bei Lohnunternehmern in der Hofduengerausbringung.',s:'Abs. 4.1.3'},
{c:'befahren',q:'Welche Massnahme vergroessert die Auflageflaeche NICHT?',o:['Reifeninnendruck vor der Feldarbeit anpassen','Mehrachsige Fahrwerke waehlen','Doppelraeder einsetzen','Schmalere Reifen montieren'],a:3,e:'Schmalere Reifen verkleinern die Auflageflaeche und erhoehen den Bodendruck.',s:'Abs. 2.3.2'},
{c:'befahren',q:'Was zeigt die Forschung zur Verdoppelung der Radlast?',o:['Die Reifenbreite muesste sich ebenfalls genau verdoppeln','Die Reifenbreite muesste sich MEHR als verdoppeln','Die Reifenbreite spielt keine Rolle','Die Reifenbreite koennte halbiert werden'],a:1,e:'Bei doppelter Radlast muesste sich die Reifenbreite mehr als verdoppeln, um den Boden nicht zusaetzlich zu verdichten.',s:'Abs. 2.3.2'},
{c:'befahren',q:'Warum wirkt sich ein hoher Tongehalt negativ auf die Befahrbarkeit aus?',o:['Ton macht den Boden leichter','Bei Naesse wirkt der feine Ton wie ein Gel, die Bodenteilchen verschmieren zu einer Pflugsohle','Ton erhoeht den pH-Wert','Ton speichert zu viel Luft'],a:1,e:'Die Bodenfestigkeit nimmt mit steigendem Wasser- und Tongehalt rasch ab.',s:'Abs. 2.1.2'},
{c:'befahren',q:'Was ist der "Teufelskreis der nassen Bodenbearbeitung"?',o:['Bearbeiten ungenuegend abgetrockneter Boeden - Schmierschicht - Wasserstau - erneut nasses Bearbeiten','Duengen - Wachsen - Ernten - Duengen','Pfluegen - Eggen - Saeen - Walzen','Regen - Sonne - Wind - Frost'],a:0,e:'Ein einmal entstandener Wasserstau sorgt dafuer, dass der Boden auch im Folgejahr nur langsam abtrocknet.',s:'Abs. 2.1.2'},
{c:'befahren',q:'Welcher Grundsatz gilt bei nassen Verhaeltnissen?',o:['Schnell arbeiten, bevor es noch nasser wird','Das Dringendste ist, dass man wartet','Mit leichteren Geraeten trotzdem arbeiten','Nur nachts arbeiten'],a:1,e:'"Das Dringendste ist, dass man wartet" - gute Praxis bei nassen Verhaeltnissen.',s:'Abs. 2.1.4'},
{c:'befahren',q:'Welches Online-Tool hilft bei der Abschaetzung der Verdichtungsgefaehrdung?',o:['Terranimo','Agrometeo','Feldkalender','Bodenmessnetz'],a:0,e:'Terranimo.ch berechnet die Verdichtungsgefaehrdung aus Radlast, Reifendruck, Bodenart und Feuchtigkeit.',s:'L34 / Abs. 2.4'},
{c:'befahren',q:'Bei welchen Bedingungen besteht ein hohes Verdichtungsrisiko?',o:['Nasser Boden, hoher Tongehalt, hohe Radlast, kleine Auflageflaeche, hoher Reifendruck, unbewachsener Boden','Trockener Sandboden mit Bewuchs','Gefrorener Boden','Bewachsene Wiese im Sommer'],a:0,e:'Alle sechs Faktoren erhoehen das Risiko und treten in der Praxis oft kombiniert auf.',s:'Abs. 2.4'},
{c:'befahren',q:'Wann sollten Feldarbeiten im fruehen Fruehjahr idealerweise stattfinden?',o:['Am Nachmittag bei Waerme','Wenn die obersten 2 bis 3 cm des Bodens gefroren sind, also vor dem Auftauen','Bei Regen','Nach dem Auftauen'],a:1,e:'Gefrorene Oberflaeche reduziert die Druckfortpflanzung stark.',s:'Abs. 2.4.1'},
{c:'befahren',q:'Wenn am naechsten Tag Regen angesagt ist und noch gesaet werden muss - wann saeen?',o:['Am Vormittag','Am Nachmittag, weil der Boden tagsueber abtrocknet','In der Nacht','Gar nicht'],a:1,e:'Durch das Abtrocknen waehrend des Tages ist das Verdichtungsrisiko am Nachmittag geringfuegig kleiner.',s:'Abs. 2.4.1'},
{c:'befahren',q:'Was ist eine Pflugsohle?',o:['Die Unterseite des Pfluges','Eine verdichtete Schicht auf Pflugtiefe, die kein Wasser und keine Wurzeln durchlaesst','Die Oberflaeche nach dem Pfluegen','Ein Ersatzteil am Traktor'],a:1,e:'Sie entsteht durch Schmieren der Pflugschare sowie Schlupf und Druck der Traktorraeder in der Pflugfurche.',s:'L-Begriffe / Abs. 4.2'},
{c:'befahren',q:'Welche Folge hat eine Pflugsohle?',o:['Bessere Wasserspeicherung','Gestoerte Wasserversickerung, Staunaesse, Sauerstoffmangel, gefoerderte Wurzelfaeulen','Hoehere Ertraege','Mehr Regenwuermer'],a:1,e:'Zuckerrueben koennten ohne Pflugsohle bis 1.5 m tief wurzeln - mit Pflugsohle reagieren sie empfindlich auf Trockenheit.',s:'Abs. 4.2'},
{c:'befahren',q:'Warum ist bewachsener Boden weniger verdichtungsanfaellig?',o:['Weil die Pflanzen Wasser aufnehmen','Weil gut durchwurzelte Boeden bedeutend tragfaehiger sind als frisch bearbeitete Flaechen','Weil Pflanzen den pH-Wert heben','Weil die Blaetter das Gewicht abfangen'],a:1,e:'Je lockerer der Boden nach einer Bearbeitung, desto tiefer sind die Fahrspuren nach einer Befahrung.',s:'Abs. 2.1.1'},

/* ===== 9. PFLUG, GRUBBER & GRUNDBODENBEARBEITUNG ===== */
{c:'grundboden',q:'Welche drei Arten der Bodenbearbeitung werden unterschieden?',o:['Stoppelbearbeitung, Grundbodenbearbeitung, Saatbettbereitung','Pfluegen, Eggen, Walzen','Fruehjahr, Sommer, Herbst','Flach, mittel, tief'],a:0,e:'Diese drei Arbeitsschritte unterscheiden sich in Tiefe und Ziel.',s:'Abs. 1.3'},
{c:'grundboden',q:'Wie tief arbeitet die Grundbodenbearbeitung?',o:['3 bis 4 cm','unter 10 cm','15 bis 25 cm','ueber 50 cm'],a:2,e:'Grundbodenbearbeitung bedeutet Wenden, Mischen oder Lockern auf 15 bis 25 cm mit Pflug oder Grubber.',s:'L36 / Abs. 1.3.2'},
{c:'grundboden',q:'Wie tief soll die Saatbettbereitung erfolgen?',o:['flach bis etwa 10 cm','15 bis 25 cm','30 cm','ueber 40 cm'],a:0,e:'Die Saatbettbereitung soll flach bis etwa zehn Zentimeter Bodentiefe erfolgen.',s:'Abs. 1.3.3'},
{c:'grundboden',q:'Was bedeutet "intensive Bodenbearbeitung"?',o:['Nur tiefes Arbeiten','Je tiefer, je feiner zerschlagen, je haeufiger und je staerker gewendet, desto intensiver','Nur haeufiges Arbeiten','Nur das Wenden mit dem Pflug'],a:1,e:'Alle vier Faktoren zusammen bestimmen, wie stark die Bodenstruktur veraendert wird.',s:'L2a'},
{c:'grundboden',q:'Welche zwei Arbeitsgeraete haben eine besonders intensive Wirkung?',o:['Walze und Federzinkenegge','Pflug (grosse Arbeitstiefe plus Wenden) und zapfwellenbetriebene Eggen','Grubber und Stoppelhobel','Saemaschine und Packer'],a:1,e:'Zapfwellenbetriebene Eggen zerschlagen den Boden feiner als gezogene Geraete.',s:'L2b'},
{c:'grundboden',q:'Was ist das Hauptziel der Stoppelbearbeitung?',o:['Den Boden tief lockern','Oberflaechliches Aufreissen und Durchmischen des Stoppelackers','Das Saatbett fertigstellen','Den Boden wenden'],a:1,e:'Oberflaechliches Aufreissen und Durchmischen mit Grubber oder Egge, etwa 3 bis 4 cm tief.',s:'L-Begriffe / Abs. 3'},
{c:'grundboden',q:'Welche Wirkung wird mit der Stoppelbearbeitung NICHT angestrebt?',o:['Fahrspuren aufbrechen','Kapillaritaet unterbinden, um Wasserverlust zu verringern','Den Boden auf 25 cm lockern','Ausfallsamen und Unkraeuter zur Keimung anregen'],a:2,e:'Tiefe Lockerung ist Sache der Grundbodenbearbeitung. Die Stoppelbearbeitung arbeitet oberflaechlich.',s:'Abs. 3'},
{c:'grundboden',q:'Warum sollte die Stoppelbearbeitung bei knappen Wasserverhaeltnissen rasch nach der Ernte erfolgen?',o:['Weil der Boden sonst zu hart wird','Weil die unterbrochenen Kapillaren den Aufstieg und die Verdunstung des Bodenwassers verhindern','Weil sonst Unkraut keimt','Weil die Maschinen frei sind'],a:1,e:'Das im Boden verbliebene Wasser steht so der Folgekultur zur Verfuegung.',s:'Abs. 3'},
{c:'grundboden',q:'Welche Ausnahme gilt bei der Stoppelbearbeitung nach Raps?',o:['Sie muss besonders tief erfolgen','Ausgefallene Rapskoerner sollten vor der Stoppelbearbeitung gekeimt haben, sonst gibt es spaeter Durchwuchs','Sie darf gar nicht erfolgen','Sie muss zweimal erfolgen'],a:1,e:'Raps ist Lichtkeimer - vergrabene Samen fuehren in den kommenden Jahren zu Durchwuchs.',s:'Abs. 3 / L35'},
{c:'grundboden',q:'Wie lang sollte das Stroh nach dem Dreschen maximal sein?',o:['Nicht viel laenger als ein Kugelschreiber','Etwa 50 cm','Moeglichst lang','Genau 1 Meter'],a:0,e:'Kurz gehaeckselte Reste haben eine grosse Oberflaeche und verrotten rascher.',s:'Abs. 3'},
{c:'grundboden',q:'Wie erkennt man eine erfolgreiche Stoppelbearbeitung?',o:['Der Boden ist komplett schwarz','Die Rueckstaende sind gleichmaessig und intensiv mit Erde vermischt - keine Matratzen und keine Strohhaufen','Es liegt viel Stroh obenauf','Der Boden ist sehr fein'],a:1,e:'Dicke Matratzen aus organischem Material und Strohhaufen sind Zeichen mangelhafter Arbeit.',s:'Abs. 3'},
{c:'grundboden',q:'Warum ist die Stoppelbearbeitung im Biolandbau besonders wichtig?',o:['Wegen der Duengung','Wegen der Wirkung auf die Unkraeuter','Wegen der Bodenerwaermung','Wegen der Erosion'],a:1,e:'Ein zweiter Durchgang schaedigt oder ueberschuettet neu gekeimte Unkraeuter und verringert den Unkrautdruck.',s:'Abs. 3'},
{c:'grundboden',q:'Warum wird beim zweiten Stoppelbearbeitungs-Durchgang im Biolandbau KEINE Walze eingesetzt?',o:['Um Zeit zu sparen','Damit die ausgerissenen Pflanzen nicht wieder angedrueckt werden, sondern verdorren','Um Treibstoff zu sparen','Weil der Boden zu nass ist'],a:1,e:'Beim ersten Durchgang foerdert die Walze die Keimung der Unkraeuter, beim zweiten wuerde sie sie wieder anwachsen lassen.',s:'Abs. 3 / L43'},
{c:'grundboden',q:'Welche zwei Geraete eignen sich fuer die Grundbodenbearbeitung?',o:['Pflug und Grubber','Walze und Egge','Saemaschine und Packer','Maehdrescher und Haecksler'],a:0,e:'Pflug und Grubber lockern den Boden zwischen rund 15 und 25 cm.',s:'Abs. 4'},
{c:'grundboden',q:'Was bewirkt der Pflug?',o:['Er lockert nur','Er wendet UND lockert den Boden','Er verdichtet den Boden','Er saet gleichzeitig'],a:1,e:'Der Pflug hinterlaesst eine von Ernterueckstaenden und Fremdbewuchs freie Ackeroberflaeche.',s:'Abs. 4.1'},
{c:'grundboden',q:'Welcher Vorteil spricht fuer den Pflug?',o:['Er schont die Regenwuermer','Verstopfungsfreier Einsatz von Saat- und Hackgeraeten, kein Totalherbizid noetig, schnelleres Abtrocknen','Er verbraucht wenig Treibstoff','Er erhoeht den Humusgehalt'],a:1,e:'Weitere Vorteile: tieferer Krankheitsdruck, weniger Schaedlinge, Wintergare, Maeusebekaempfung, Einarbeitung von Zwischenkulturen.',s:'L30 / S.30'},
{c:'grundboden',q:'Welcher Nachteil ist typisch fuer den Pflug?',o:['Hoher Treibstoffverbrauch, schlechtere Bodenstruktur, hoeheres Erosions- und Verdichtungsrisiko','Zu langsames Abtrocknen','Zu viele Bodenlebewesen','Zu wenig Zugkraftbedarf'],a:0,e:'Weitere Nachteile: weniger Bodenlebewesen, rasches Austrocknen, Matratzen durch organisches Material, schnellerer Humusabbau.',s:'L30 / S.30'},
{c:'grundboden',q:'Wie viel Wasser kann ein Boden durch den Pflugeinsatz verlieren?',o:['bis 5 l/m2','bis 30 l/m2','bis 100 l/m2','gar keines'],a:1,e:'Als Faustregel verliert ein Boden durch Pfluegen bis zu 30 Liter Wasser pro Quadratmeter.',s:'S.31'},
{c:'grundboden',q:'Welche Umschichtung bedeutet jeder zusaetzliche Zentimeter Bearbeitungstiefe?',o:['rund 15 Tonnen Boden pro Hektare','rund 150 Tonnen Boden pro Hektare','rund 1500 Tonnen Boden pro Hektare','rund 1 Tonne pro Hektare'],a:1,e:'Jeder Zentimeter bedeutet eine Umschichtung von rund 150 Tonnen Boden pro Hektare - unnoetig tief kostet Treibstoff und schaedigt die Struktur.',s:'Abs. 4.1.2'},
{c:'grundboden',q:'Welche drei Fehler beim Pfluegen sind typisch?',o:['Zu tief pfluegen, bei nassem Boden pfluegen, falsche Zugpunkt-Einstellung','Zu schnell fahren, zu spaet saeen, zu wenig duengen','Zu flach pfluegen, zu trockener Boden, zu breite Reifen','Zu wenig wenden, zu viel walzen, zu frueh ernten'],a:0,e:'Langzeitfolgen: unregelmaessiges Aufwachsen der Kultur und Ertragseinbussen.',s:'L37'},
{c:'grundboden',q:'Was passiert, wenn man zu tief pfluegt?',o:['Der Boden wird fruchtbarer','Unterboden mit viel Feinerde oder grosse Steine gelangen an die Oberflaeche - Verschlaemmung und Erosion nehmen zu','Der Humusgehalt steigt','Es entsteht mehr Wintergare'],a:1,e:'Wenig tragfaehiger, strukturschwacher Unterboden an der Oberflaeche fuehrt zu vermehrter Verschlaemmung und Erosion.',s:'L37 / Abs. 4.1.2'},
{c:'grundboden',q:'Was ist die Folge einer falschen Zugpunkt-Einstellung am Pflug?',o:['Zu hoher Zugkraftbedarf, dadurch Schlupf und Verschmierung','Der Boden wird zu locker','Der pH-Wert sinkt','Das Saatbett wird zu grob'],a:0,e:'Zu hoher Zugkraftbedarf fuehrt zu Schlupf und damit zu Verschmierung.',s:'L37'},
{c:'grundboden',q:'Welchen Vorteil hat der On-Land-Pflug?',o:['Er ist guenstiger in der Anschaffung','Keine Pflugsohle, weil nicht in der Pflugfurche sondern auf dem gewachsenen Boden gefahren wird','Er arbeitet tiefer','Er braucht weniger Zugkraft'],a:1,e:'Das ganze Traktorgewicht stuetzt sich auf der tragfaehigen, ungelockerten Oberflaeche ab.',s:'L54 / S.31'},
{c:'grundboden',q:'Welche Nachteile hat der On-Land-Pflug?',o:['Hoehere Anschaffungskosten, mehr Schlupf, mehr seitliche Kraefte - schwieriger genau zu fahren','Er erzeugt eine Pflugsohle','Er ist zu langsam','Er wendet den Boden nicht'],a:0,e:'Das Fahren ausserhalb der Furche stellt hoehere Anforderungen an den Fahrer, besonders am Hang.',s:'L54 / S.31'},
{c:'grundboden',q:'Wie arbeitet ein Schaelpflug (Stoppelhobel)?',o:['Er pflugt besonders tief','Nur ganz flache Arbeitstiefe - die obersten paar Zentimeter werden gewendet','Er lockert ohne zu wenden','Er verdichtet den Boden'],a:1,e:'Durch die oberflaechliche Bearbeitung wird das Gefuege wenig belastet und der Zugkraftbedarf ist gering.',s:'L55 / S.31'},
{c:'grundboden',q:'Welchen Vorteil hat der Schaelpflug bei Wurzelunkraeutern?',o:['Er zerteilt sie besonders fein','Durch das Fehlen des Vorschaelers werden Wurzelunkraeuter weniger zerteilt als beim herkoemmlichen Pflug','Er toetet sie chemisch ab','Er hat keine Wirkung'],a:1,e:'Deshalb ist er besonders im Biolandbau bedeutsam.',s:'S.31'},
{c:'grundboden',q:'Was ist die Herbstfurche?',o:['Das Pfluegen im Spaetherbst bei noch trockenen Verhaeltnissen','Das Saeen im Herbst','Die Ernte im Herbst','Das Duengen im Herbst'],a:0,e:'Der Boden bleibt im Winter brach, Frost zerkleinert die Schollen - man spricht von Frostsprengung.',s:'L56 / S.31'},
{c:'grundboden',q:'Was ist die Frostgare?',o:['Ein Duengemittel','Das durch Frostsprengung fein zerkleinerte Gefuege, das die Saatbettbereitung im Fruehjahr erleichtert','Eine Krankheit','Ein Bodentyp'],a:1,e:'Der Frost zerkleinert die Erdklumpen durch Gefrieren und Auftauen - eine "Gratisauflockerung".',s:'L56 / S.31'},
{c:'grundboden',q:'Wo ist die Herbstfurche NICHT empfehlenswert?',o:['In flachem Gelaende','Auf schluffigen Boeden und in Hanglagen - wegen des hohen Erosionsrisikos','Auf Tonboeden','Auf Sandboeden'],a:1,e:'Schluffige Boeden, Hanglagen und unbedeckte Oberflaechen haben ein ausserordentlich hohes Erosionsrisiko.',s:'S.31'},
{c:'grundboden',q:'Warum sollte waehrend der Winterruhe nicht gepfluegt werden?',o:['Weil der Traktor nicht faehrt','Weil die Bodenlebewesen nicht aktiv sind, die Lebendverbauung unterbleibt und die Auswaschungsgefahr steigt','Weil es zu kalt ist fuer Diesel','Weil der Boden gefroren ist'],a:1,e:'Der Boden kann sich nach dem Eingriff nicht erholen, zudem steigt die Nitratauswaschung.',s:'S.31'},
{c:'grundboden',q:'Was bewirkt der Grubber?',o:['Er wendet den Boden','Er lockert den Boden, ohne ihn zu wenden','Er verdichtet den Boden','Er saet gleichzeitig'],a:1,e:'Der Grubber lockert und mischt. Unkraeuter werden von Erdmaterial bedeckt und entwurzelt.',s:'Abs. 4.3'},
{c:'grundboden',q:'Welche Vorteile hat der Grubber gegenueber dem Pflug?',o:['Rund doppelte Flaechenleistung bei geringerem Dieselbedarf, bessere Durchmischung von Pflanzenrueckstaenden, foerdert Verrottung und Bodenleben','Er wendet den Boden besser','Er bekaempft Krankheiten besser','Er hinterlaesst eine saubere Oberflaeche'],a:0,e:'Zudem werden Regenwuermer und Mykorrhiza-Geflechte geschont.',s:'S.32 / Abs. 4.3'},
{c:'grundboden',q:'Welche Nachteile hat die nicht wendende Bearbeitung mit dem Grubber?',o:['Spritzschatten und mehr Schnecken, eingeschraenkter Hackgeraeteeinsatz, schlechtere Bekaempfung von Pilzkrankheiten','Hoeherer Dieselverbrauch','Geringere Flaechenleistung','Weniger Regenwuermer'],a:0,e:'Da ein Teil der Pflanzenreste an der Oberflaeche bleibt, ist die Wirkung gegen Verunkrautung und Erreger weniger ausgepraegt.',s:'S.32'},
{c:'grundboden',q:'Was ist ein Spritzschatten?',o:['Der Schatten des Traktors','Grobe Schollen oder Ernterueckstaende, die keimende Unkraeuter vor dem Spritzstrahl des Herbizids schuetzen','Ein Duesentyp','Eine Fahrspur'],a:1,e:'Spritzschatten sind ein typischer Nachteil der konservierenden Bodenbearbeitung.',s:'Abs. 5.4'},
{c:'grundboden',q:'Fuer welche Arbeiten eignet sich die FLUEGELSCHAR am Grubber?',o:['Tiefe Lockerung','Oberflaechliche Bearbeitung zum Einmischen von Ernteresten und zur Unkrautbekaempfung auf allen Boeden','Nur zum Wenden','Nur zur Saat'],a:1,e:'Fluegelscharen haben einen weiten Strichabstand und durchschneiden ganzflaechig.',s:'L38'},
{c:'grundboden',q:'Fuer welche Arbeiten eignen sich Doppelherzschar und Meisselzinken?',o:['Nur zur Stoppelbearbeitung','Grundbodenbearbeitung zum Lockern, Aufbrechen von Fahrgassen und Vergraben von Ernterueckstaenden','Nur zur Saat','Nur zum Walzen'],a:1,e:'Sie haben einen engen Strichabstand und sind fuer die Tiefenlockerung geeigneter als Fluegelscharen.',s:'L38'},
{c:'grundboden',q:'Wofuer eignet sich die GAENSEFUSSSCHAR besonders?',o:['Tiefe Lockerung','Speziell zur Bekaempfung von Wurzelunkraeutern sowie zum Einmischen von Duengern und Stoppeln auf leichten Boeden','Zum Wenden','Zum Rueckverfestigen'],a:1,e:'Gaensefussschare haben einen engen Strichabstand und koennen etwas oberflaechlicher arbeiten als andere Schare.',s:'L38 / Abs. 4.3.1'},
{c:'grundboden',q:'Was ist der Strichabstand?',o:['Der Abstand zwischen zwei Fahrspuren','Die kuerzeste Distanz zwischen den gezogenen Bearbeitungslinien','Die Arbeitsbreite des Geraets','Der Abstand zwischen Saatreihen'],a:1,e:'Die Arbeitstiefe sollte in der Regel mindestens dem Strichabstand entsprechen.',s:'Abs. 4.3.1'},
{c:'grundboden',q:'Welche Regel gilt fuer Arbeitstiefe und Strichabstand beim Grubber?',o:['Die Arbeitstiefe soll mindestens dem Strichabstand entsprechen','Die Arbeitstiefe soll halb so gross sein wie der Strichabstand','Beides ist unabhaengig','Die Arbeitstiefe soll doppelt so gross sein'],a:0,e:'Eine Ausnahme bilden Gaensefussschare, die etwas oberflaechlicher arbeiten koennen.',s:'Abs. 4.3.1'},
{c:'grundboden',q:'Welche Ursachen fuehren zu Bodenverschmierung beim Grubbern?',o:['Zu feuchter Boden, stumpfe Werkzeuge, zu breite Scharen','Zu trockener Boden und scharfe Werkzeuge','Zu hohe Geschwindigkeit','Zu geringe Arbeitstiefe'],a:0,e:'Die Folge ist Behinderung des Wurzelwachstums und des Gasaustausches.',s:'Abs. 4.3.2'},
{c:'grundboden',q:'Was verursacht einen hohen Treibstoffverbrauch beim Grubbern?',o:['Zu feuchter Boden','Zu trockener Boden, stumpfe Werkzeuge und zu tiefe Bearbeitung','Zu breite Reifen','Zu langsame Fahrt'],a:1,e:'Unnoetig tief bearbeiteter Boden kostet Treibstoff und schaedigt zusaetzlich die Struktur.',s:'Abs. 4.3.2'},
{c:'grundboden',q:'Was fuehrt zu ungenuegender Durchmischung von Ernterueckstaenden?',o:['Zu grosser Strichabstand, zu geringe Tiefe, zu geringe Fahrgeschwindigkeit, falsche Scharwahl','Zu kleine Reifen','Zu hoher Humusgehalt','Zu viel Kalk'],a:0,e:'Auch zu nasse Bodenverhaeltnisse spielen eine Rolle.',s:'Abs. 4.3.2'},
{c:'grundboden',q:'Wann wuerde man einen Pflug einsetzen statt einen Grubber?',o:['Beim Umbruch einer Kunstwiese, damit die Grasschollen abgetoetet werden','Beim Aeugstlen nach Getreide','Bei leichten Boeden im Sommer','Bei Direktsaat'],a:0,e:'Der Pflug wendet die Grasschollen nach unten - das Gras stirbt ab. Mit dem Grubber wuerde es wieder anwachsen.',s:'L36'},
{c:'grundboden',q:'Wann genuegt der Grubber statt des Pflugs?',o:['Beim Kunstwiesenumbruch','Bei der Ansaat einer Kunstwiese nach Getreide (Aeugstlen) - zum Lockern von Verdichtungen genuegt der Grubber','Vor Kartoffelanbau','Nach Mais vor Weizen'],a:1,e:'Der Grubber ist bodenschonender und verbraucht weniger Treibstoff.',s:'L36'},
{c:'grundboden',q:'Welche Situation spricht eher FUER den Pflug?',o:['Nach Weizenernte vor Rapssaat, wenn Stroh abtransportiert wurde','In einem schweren Boden mit leichter Bodenverdichtung und vor Kartoffelanbau','Im Biolandbau nach Getreide vor Kunstwiesenansaat','In einem leichten Boden, der im Sommer austrocknet'],a:1,e:'Bei leichter Verdichtung in schwerem Boden und vor Kartoffeln ist der Pflug sinnvoll; die anderen drei Situationen sprechen fuer pfluglos.',s:'L58'},
{c:'grundboden',q:'Warum werden im Biolandbau tiefe Eingriffe mit Pflug oder Grubber nach Moeglichkeit vermieden?',o:['Wegen der Kosten','Um Lebewesen wie den Regenwurm zu schonen und Naehrstoffverluste zu vermeiden','Weil es verboten ist','Weil die Maschinen fehlen'],a:1,e:'Gewachsener Boden mit intaktem Pilzgeflecht unterstuetzt das aktive Bodenleben und speichert Naehrstoffe.',s:'Abs. 1.3.4'},
{c:'grundboden',q:'Warum wird der Pflug im Biolandbau trotzdem oft eingesetzt?',o:['Weil er billiger ist','Weil kuenstlich hergestellte Pflanzenschutzmittel nicht zugelassen sind und der Pflug als Herbizid- und teilweise Fungizid-Ersatz dient','Weil er schneller ist','Weil er Humus aufbaut'],a:1,e:'Der Mittelweg: Pflug einsetzen, aber nur unter guenstigen Bedingungen und nicht zu tief.',s:'Abs. 1.3.4 / S.31'},
{c:'grundboden',q:'Welche Aussage zur Scheibenegge ist RICHTIG?',o:['Sie eignet sich gut bei Ackerwinden','Auf einer Parzelle mit vielen Ackerwinden sollte keine Scheibenegge eingesetzt werden','Sie lockert tiefe Verdichtungen','Sie arbeitet langsamer als der Grubber'],a:1,e:'Schneidende Werkzeuge vermehren Wurzelunkraeuter. Die Scheibenegge hat aber eine hoehere Flaechenleistung als der Grubber.',s:'L57'},
{c:'grundboden',q:'Welche Aussage ist FALSCH?',o:['Mit einer Scheibenegge hat man 1 ha schneller bearbeitet als mit einem Grubber','In trockenen Boeden wird mit einer Kreiselegge die Bodenstruktur geschaedigt','Fuer die Auflockerung von tiefen Bodenverdichtungen eignet sich die Zinkenegge sehr gut','Nach der Getreideernte laesst sich Stroh nur schlecht mit einer Zinkenegge einarbeiten'],a:2,e:'Die Zinkenegge arbeitet flach und eignet sich NICHT zur Auflockerung tiefer Verdichtungen.',s:'L57'},
{c:'grundboden',q:'Welche Geraete lassen sich nicht wendend fuer die Tiefenlockerung verdichteter Boeden einsetzen?',o:['Kreiselegge und Bodenfraese','Parapflug oder Rotationsspaten','Walze und Packer','Saemaschine'],a:1,e:'Wichtig ist, guenstige Bedingungen abzuwarten - bei nassem Boden entstehen sonst zusaetzliche Schmier- und Knetspuren.',s:'S.17'},

/* ===== 10. SAATBETT, SAATTECHNIK & DIREKTSAAT ===== */
{c:'saatbett',q:'Was ist das Ziel der Saatbettbereitung?',o:['Den Boden moeglichst fein zu machen','Fuer Keimling und junge Pflanze ein optimales Umfeld bezueglich Wasser, Luft, Waerme und Durchwurzelbarkeit zu schaffen','Den Boden zu verdichten','Unkraut zu foerdern'],a:1,e:'Das Saatbett soll nicht zu fein und zugleich rueckverfestigt sein.',s:'Abs. 5'},
{c:'saatbett',q:'Welche Voraussetzungen braucht ein Saatkorn zur Keimung neben Wasser?',o:['Waerme, Luft, Bodenkontakt und zum Teil Licht','Duenger, Kalk und Humus','Ton, Sand und Schluff','Nur Waerme'],a:0,e:'Bodenschluss ist entscheidend, bei Lichtkeimern wie Raps zusaetzlich Licht.',s:'L39'},
{c:'saatbett',q:'Wie wird der Fuenflibertest durchgefuehrt?',o:['Mit dem Doppelmeter ein Rechteck von 40 x 60 cm auslegen und die Schollen beurteilen und auszaehlen','Eine Muenze in den Boden werfen','Fuenf Bodenproben nehmen','Den Boden fuenfmal durchsieben'],a:0,e:'Einen Doppelmeter zu einem Rechteck von 40 mal 60 cm falten und auf die bearbeitete Flaeche legen.',s:'L41a'},
{c:'saatbett',q:'Wie sieht ein Saatbett aus, das den Fuenflibertest bestanden hat?',o:['Nur feine Erde','Mindestens 20 Aggregate so gross wie ein Fuenfliber plus 3 bis 5 faustgrosse Schollen','Nur grosse Schollen','Genau 10 Aggregate'],a:1,e:'Mindestens 20 Aggregate in Fuenfliber-Groesse und zusaetzlich 3 bis 5 faustgrosse Schollen.',s:'L41b / Abs. 5'},
{c:'saatbett',q:'Bei welchem Saatgut ist ein FEINES Saatbett zweckmaessig?',o:['Bei Mais und Bohnen','Bei kleinkoernigem Saatgut wie Gemuese oder Kunstwiesenmischungen','Bei Getreide','Bei Kartoffeln'],a:1,e:'Fuer die meisten ackerbaulichen Kulturen ist der Fuenflibertest der richtige Massstab - nur kleinkoerniges Saatgut braucht ein feines Saatbett.',s:'Abs. 5'},
{c:'saatbett',q:'Welche Korngroessen ueberwiegen im OBEREN Bereich eines optimalen Saatbetts?',o:['Feinerde von wenigen Millimetern','Groebere Bodenteilchen von fuenflibergross bis faustgross','Nur Staub','Nur Steine'],a:1,e:'Die groeberen Teilchen schuetzen die feinen Bodenteilchen vor dem Regen - Schutz vor Verschlaemmung und Erosion.',s:'L40'},
{c:'saatbett',q:'Welche Korngroessen ueberwiegen auf SAATTIEFE in einem optimalen Saatbett?',o:['Faustgrosse Schollen','Feinerde von wenigen Millimetern','Grobe Steine','Nur Ton'],a:1,e:'Die Feinerde umschliesst den Keimling, fuehrt Wasser durch Kapillarwirkung zu und gibt der Keimwurzel Halt.',s:'L40'},
{c:'saatbett',q:'Welche Gefahr besteht bei einem zu FEINEN Saatbett?',o:['Der Keimling faellt zu tief','Verschlaemmung und Erosion','Zu wenig Bodenschluss','Zu langsame Keimung'],a:1,e:'Bei feinschollig bearbeitetem Boden steigt das Risiko der Verschlaemmung und Erosion stark an.',s:'Abs. 5'},
{c:'saatbett',q:'Welche Gefahr besteht bei einem zu GROBEN Saatbett?',o:['Verschlaemmung','Kein kapillarer Wasseraufstieg, kein Bodenschluss und mehr Schnecken - das Auflaufen ist gefaehrdet','Zu viel Erosion','Zu schnelle Keimung'],a:1,e:'Ziel ist ein Mittelweg zwischen zu feiner und zu grober Bearbeitung.',s:'Abs. 5'},
{c:'saatbett',q:'Was ist Verschlaemmung?',o:['Das Austrocknen des Bodens','Aufschwemmen feiner Bodenteilchen bei Regen - die Poren fuellen sich, Wasser versickert nicht mehr, es bildet sich eine Kruste','Das Verdichten durch Raeder','Das Wenden mit dem Pflug'],a:1,e:'Verschlaemmung fuehrt oft zu Erosion und kann im Extremfall das Auflaufen der Kultur verhindern.',s:'L-Begriffe / Abs. 5'},
{c:'saatbett',q:'Wie laeuft der Verschlaemmungsprozess ab?',o:['Kruemel durch intensive Bearbeitung beschaedigt - Regen schwemmt feine Teilchen aus - Poren fuellen sich - Wasser fliesst oberflaechlich ab - Erosion','Frost - Auftauen - Lockerung - Setzung','Duengen - Wachsen - Ernten','Pfluegen - Eggen - Saeen'],a:0,e:'Der Prozess laeuft vor allem auf zu intensiv bearbeiteten Ackerflaechen ab.',s:'L44'},
{c:'saatbett',q:'Wie laesst sich ein zu fein geratenes Saatbett bei der Kreiselegge korrigieren?',o:['Langsamer fahren','Stauschild hochstellen, schneller fahren, Drehgeschwindigkeit der Rotoren oder Zapfwellendrehzahl reduzieren','Tiefer arbeiten','Mehr walzen'],a:1,e:'Zapfwellendrehzahl von 1000er auf 540er reduzieren und die Einstell-Tabelle an der Maschine beachten.',s:'L42'},
{c:'saatbett',q:'Was gilt fuer die Fahrgeschwindigkeit bei zapfwellenbetriebenen Eggen?',o:['Je langsamer der Traktor faehrt, desto intensiver die Bearbeitung','Je schneller, desto intensiver','Die Geschwindigkeit spielt keine Rolle','Nur die Arbeitstiefe zaehlt'],a:0,e:'Auch eine hoehere Zapfwellendrehzahl steigert die Intensitaet.',s:'Abs. 5.2.3'},
{c:'saatbett',q:'Mit welcher Geschwindigkeit werden gezogene Eggen ueblicherweise gezogen?',o:['2 bis 4 km/h','8 bis 10 km/h','15 bis 20 km/h','ueber 25 km/h'],a:1,e:'Zu langsam gezogene Eggen kruemeln den Boden nicht genuegend, weil die Vibration zu gering ausfaellt.',s:'Abs. 5.1.3'},
{c:'saatbett',q:'Welches Geraet ist am aggressivsten?',o:['Ruettelegge','Kreiselegge','Bodenfraese','Zinkenrotor'],a:3,e:'Reihenfolge der Aggressivitaet absteigend: Zinkenrotor, Bodenfraese, Kreiselegge, Ruettelegge.',s:'Abs. 5.2.1'},
{c:'saatbett',q:'Warum hinterlaesst die Bodenfraese oft eine Schmierschicht?',o:['Weil sie zu langsam arbeitet','Wegen ihrer ganzflaechigen, vertikal rotierenden Arbeitsweise - die Wasserversickerung wird beeintraechtigt','Weil sie zu flach arbeitet','Weil sie zu breit ist'],a:1,e:'Deshalb gilt auch hier: der Boden muss genuegend abgetrocknet sein.',s:'Abs. 5.2.3'},
{c:'saatbett',q:'Welchen Unterschied gibt es zwischen Kreiselegge und Bodenfraese?',o:['Es gibt keinen','Die Kreiselegge arbeitet horizontal und sortiert die Bodenteilchen (grobe oben), die Bodenfraese hat diesen Sortiereffekt nicht','Die Bodenfraese ist schonender','Die Kreiselegge mischt besser'],a:1,e:'Durch die horizontale Arbeitsweise der Kreiselegge verbleiben Ernterueckstaende oben und die Teilchen werden sortiert.',s:'Abs. 5.2.1'},
{c:'saatbett',q:'Welche vier Funktionen hat eine Walze?',o:['Tiefenfuehrung, Zerdruecken grober Schollen, Rueckverfestigen, ebenes Saatbett herstellen','Wenden, Lockern, Saeen, Duengen','Nur Rueckverfestigen','Erosion foerdern'],a:0,e:'Die Walze gewaehrleistet zudem Bodenschluss und kapillaren Wasseraufstieg.',s:'L43 / Abs. 5.4'},
{c:'saatbett',q:'Wann soll bei der Stoppelbearbeitung NICHT rueckverfestigt werden?',o:['Immer soll rueckverfestigt werden','Bei der Stoppelbearbeitung zur Unkrautbekaempfung, damit die Unkraeuter keinen Bodenschluss haben','Nur bei nassem Boden','Nur im Herbst'],a:1,e:'Ohne Bodenschluss keimen Samen und Keimlinge der Unkraeuter nicht an, sondern verdorren.',s:'L43'},
{c:'saatbett',q:'Welche Wirkung haben schmale Walzenelemente?',o:['Sie verfestigen nur den Oberboden','Je schmaler die Elemente, desto staerker wird der Boden in der Tiefe verfestigt','Sie haben keine Wirkung','Sie lockern den Boden'],a:1,e:'Breite Elemente verfestigen nur den Oberboden.',s:'Abs. 5.4'},
{c:'saatbett',q:'Welchen Zweck hat eine Packerwalze an der Front des Traktors bei der Saat?',o:['Gewicht ausgleichen','Rueckverfestigung, um die Kapillarwirkung zu gewaehrleisten','Den Boden lockern','Unkraut bekaempfen'],a:1,e:'Ueber die Fronthydraulik kann zusaetzlich Vorderachsgewicht auf die Walze uebertragen werden.',s:'L60 / Abs. 3.7'},
{c:'saatbett',q:'Welcher Packer eignet sich fuer trockene Verhaeltnisse?',o:['Breite Packraeder','Je scharfkantiger die Packerringe und je groesser das Gewicht, desto besser fuer trockene Verhaeltnisse','Leichte Spiralpacker','Reifenpacker'],a:1,e:'Breite Packraeder sind hingegen in feuchten Boeden sinnvoll.',s:'Abs. 3.7'},
{c:'saatbett',q:'Welche zwei Typen von Saekoerpern werden unterschieden?',o:['Schleppschar und Scheibenschar','Fluegelschar und Meisselschar','Gaensefussschar und Doppelherzschar','Walze und Packer'],a:0,e:'Schleppschare sind einfach und guenstig, Scheibenschare arbeiten praeziser und verstopfen weniger.',s:'S.36'},
{c:'saatbett',q:'Warum sollte man bei vielen Ernterueckstaenden Scheibenschare bevorzugen?',o:['Weil sie guenstiger sind','Weil sie mit ihren V-foermigen Scheiben besser eindringen und weniger verstopfungsanfaellig sind; die Tiefenfuehrung wird durch Druckrollen reguliert','Weil sie tiefer arbeiten','Weil sie schneller sind'],a:1,e:'Jede Druckrolle passt sich dem Boden an und gewaehrleistet eine exakte Saattiefe.',s:'L59 / S.36'},
{c:'saatbett',q:'In welchen Situationen sind Schleppschare NICHT geeignet?',o:['Bei ebenem, feinem Saatbett','Bei vielen oder groben Pflanzenresten, steinigen Boeden, unebenen Saatbetten, schneller Fahrt und Direktsaat','Bei Getreide','Bei trockenem Boden'],a:1,e:'Die Tiefenfuehrung wird zentral eingestellt - bei wechselnden Boeden ist staendige Anpassung noetig.',s:'S.36'},
{c:'saatbett',q:'Was ist eine Bestellkombination?',o:['Eine Bestellung beim Haendler','Zwei oder mehr Arbeitsschritte werden in einer Ueberfahrt ausgefuehrt, meist Kreiselegge plus Saemaschine','Eine Fruchtfolge','Ein Duengerplan'],a:1,e:'Teilweise werden Geraete im Front- und andere im Heckanbau eingesetzt.',s:'S.34'},
{c:'saatbett',q:'Welchen Vorteil bringt eine Bestellkombination?',o:['Weniger Ueberfahrten, dadurch geringeres Verdichtungsrisiko und Zeitersparnis','Tiefere Anschaffungskosten','Geringeres Traktorgewicht','Bessere Unkrautbekaempfung'],a:0,e:'Wird zusaetzlich auf den Pflug verzichtet, erspart das bis zu zwei Arbeitsgaenge.',s:'S.34'},
{c:'saatbett',q:'Welchen Nachteil hat eine Bestellkombination?',o:['Sie braucht leistungsfaehige (und damit schwere) Traktoren und erhoeht das Gesamtgewicht','Sie arbeitet zu flach','Sie verstopft immer','Sie braucht mehr Ueberfahrten'],a:0,e:'Das hoehere Gesamtgewicht des Zugfahrzeugs mit allen Anbaugeraeten ist bei der Planung zu beruecksichtigen.',s:'S.34'},
{c:'saatbett',q:'Was ist Direktsaat?',o:['Saat direkt nach dem Pfluegen','Der Boden wird - abgesehen von den Saescharen - ueberhaupt nicht bearbeitet','Saat ohne Duengung','Saat von Hand'],a:1,e:'Der Boden bleibt permanent bedeckt und wird nicht gelockert - das gilt als besonders bodenschonend.',s:'S.35'},
{c:'saatbett',q:'Welche Vorteile hat die Direktsaat?',o:['Minimale Erosion und Verschlaemmung, tragfaehiger Boden, hohe Flaechenleistung, viele Regenwuermer, geringe Kosten','Schnelle Bodenerwaermung','Kein Unkrautdruck','Immer hoehere Ertraege'],a:0,e:'Zudem gibt es Ressourceneffizienzbeitraege des Bundes fuer schonende Bodenbearbeitung.',s:'L30 / S.35'},
{c:'saatbett',q:'Welche Nachteile hat die Direktsaat?',o:['Totalherbizid meist noetig, langsame Bodenerwaermung, Schnecken, Maeuse, Fusarienpilze, schwere Saemaschinen, Unkrautdruck','Hoher Dieselverbrauch','Starke Erosion','Viel Verdichtung'],a:0,e:'Auch Hacken ist kaum moeglich und die Ertraege koennen tiefer ausfallen.',s:'L30 / S.35'},
{c:'saatbett',q:'Fuer welche Standorte eignet sich die Direktsaat?',o:['Verdichtete und staunasse Boeden','Eher leichte, rasch erwaermbare Boeden mit gesundem Gefuege und gutem Wasserhaushalt','Sehr schwere Tonboeden','Moorboeden'],a:1,e:'Wichtig ist zudem, dass die Ernterueckstaende gleichmaessig verteilt sind.',s:'S.35'},
{c:'saatbett',q:'Warum wird Direktsaat im Biolandbau selten eingesetzt?',o:['Weil sie zu teuer ist','Weil Herbizide im Biolandbau nicht zugelassen sind und der Unkrautdruck schwer zu beherrschen ist','Weil die Maschinen fehlen','Weil sie verboten ist'],a:1,e:'Trotz der Bodenschonung ist die Direktsaat im Biolandbau schwer regelmaessig umsetzbar.',s:'S.35'},
{c:'saatbett',q:'Welche konservierenden Saatverfahren gibt es?',o:['Mulchsaat, Streifenfraessaat, Strip-Till, Direktsaat','Pflugsaat, Eggensaat, Walzensaat','Handsaat, Maschinensaat, Drohnensaat','Fruehsaat, Spaetsaat, Nachsaat'],a:0,e:'Sie unterscheiden sich im Anteil der bewegten Bodenoberflaeche.',s:'L47'},
{c:'saatbett',q:'Wie viel Bodenoberflaeche wird bei der MULCHSAAT bewegt?',o:['ca. 25 %','ca. 50 %','100 %, aber nur in geringer Tiefe','0 %'],a:2,e:'Bei der Mulchsaat wird die ganze Flaeche bewegt, jedoch nur flach. Geeignet fuer Kunstwiese, Gruenduengung, Getreide, Mais, Raps, Rueben.',s:'L47'},
{c:'saatbett',q:'Wie viel Bodenoberflaeche wird bei der STREIFENFRAESSAAT bewegt?',o:['ca. 25 %','ca. 50 %','ca. 75 %','100 %'],a:1,e:'Geeignete Kulturen: Mais (nach Kunstwiese oder Zwischenfutter) und Raps.',s:'L47'},
{c:'saatbett',q:'Wie viel Bodenoberflaeche wird bei STRIP-TILL bewegt?',o:['0 %','25 bis 50 %','75 %','100 %'],a:1,e:'Geeignete Kulturen: Mais und Raps.',s:'L47'},
{c:'saatbett',q:'Wie viel Bodenoberflaeche wird bei der DIREKTSAAT bewegt?',o:['ca. 25 %','ca. 50 %','ca. 75 %','100 %'],a:0,e:'Nur der Saeschlitz wird bewegt. Geeignete Kulturen: Getreide, Gruenduengung, zum Teil Mais.',s:'L47'},
{c:'saatbett',q:'Welche Vorteile haben konservierende Anbausysteme langfristig gegenueber dem Pflug?',o:['Stabile Bodenstruktur, erhaltene Tragfaehigkeit, erhaltene Bodenporen und Regenwurmgaenge, erhaltene Bodenlebewesen, weniger Treibstoff','Bessere Unkrautbekaempfung','Schnellere Bodenerwaermung','Weniger Schnecken'],a:0,e:'Naehrstoffe bleiben nahe der Bodenoberflaeche und das Erosionsrisiko sinkt, weil der Boden stabiler ist.',s:'L48a'},
{c:'saatbett',q:'Welchen Vorteil hat der Pflug gegenueber den schonenden Verfahren?',o:['Geringeres Krankheitsrisiko, weil Unkraut, Krankheiten und Schaedlinge wirksam bekaempft werden','Weniger Treibstoffverbrauch','Mehr Regenwuermer','Weniger Erosion'],a:0,e:'Das Krankheitsrisiko haengt allerdings stark von der Fruchtfolge ab.',s:'L48b'},
{c:'saatbett',q:'Was ist Erosion?',o:['Das Verdichten des Bodens','Das oberflaechliche Abtragen von Erdmaterial durch Regen oder Wind','Das Austrocknen des Bodens','Das Versauern des Bodens'],a:1,e:'Erosion bedeutet Verlust von fruchtbarem Boden und tritt haeufig auf verschlaemmten Boeden auf.',s:'L-Begriffe'},
{c:'saatbett',q:'Welche Folgen hat Erosion?',o:['Verlust der Bodenfruchtbarkeit, Schaeden an der Kultur, verstopfte Drainagen, Gewaesserbelastung, hoeheres Ueberschwemmungsrisiko','Hoehere Ertraege','Bessere Struktur','Mehr Humus'],a:0,e:'Erosion kann zudem Kuerzungen der Direktzahlungen ausloesen.',s:'L45'},
{c:'saatbett',q:'Wie wirkt sich die Hangneigung auf das Erosionsrisiko aus?',o:['Linear','Ueberproportional - ein Feld mit 10 % Neigung hat fast dreimal so viel Bodenabtrag wie eines mit 5 %','Gar nicht','Umgekehrt proportional'],a:1,e:'Die Erosion nimmt mit zunehmender Hanglaenge und Hangneigung zu.',s:'Buch A1.2'},
{c:'saatbett',q:'In welche Richtung sollte an Hanglagen bewirtschaftet werden?',o:['Talwaerts','Quer zur Falllinie bzw. laengs zum Hang','Kreisfoermig','Die Richtung spielt keine Rolle'],a:1,e:'Wasser nimmt den Weg des geringsten Widerstands - Bestellung quer zur Falllinie senkt das Erosionsrisiko.',s:'L49 / Buch'},
{c:'saatbett',q:'Warum beugen Regenwuermer der Erosion vor?',o:['Sie fressen Wasser','Sie schaffen mit ihren Roehren Grobporen, die in kurzer Zeit viel Wasser aufnehmen','Sie verdichten den Boden','Sie erhoehen den pH-Wert'],a:1,e:'Zu feine Bearbeitung beguenstigt Erosion, weil sie Verschlaemmung foerdert und feine Teilchen leichter abgeschwemmt werden.',s:'Buch A1.2'},
{c:'saatbett',q:'Ab welchem Bodenabtrag gilt Erosion als "bewirtschaftungsbedingt relevant"?',o:['ab 0.5 t/ha','ab 2 oder 4 Tonnen pro Hektare, je nach Bodenmaechtigkeit','ab 20 t/ha','ab 100 t/ha'],a:1,e:'Auf Ackerflaechen darf keine bewirtschaftungsbedingt relevante Erosion auftreten.',s:'Buch A1.2'},
{c:'saatbett',q:'Was bedeutet OeLN?',o:['Oekologischer Leistungsnachweis - Vorgaben, an die sich alle Betriebe mit Direktzahlungen halten muessen','Oeffentliche Landwirtschaftsnorm','Oekologische Landnutzung','Oelverbrauchsnachweis'],a:0,e:'Der OeLN bezweckt eine umweltschonende Produktion.',s:'L-Begriffe'},
{c:'saatbett',q:'Warum muessen Bodenbearbeitungen im Parzellenblatt erfasst werden?',o:['Aus Steuergruenden','Es ist Voraussetzung fuer den OeLN - fehlende oder lueckenhafte Eintraege koennen zu Kuerzungen der Direktzahlungen fuehren','Fuer die Versicherung','Fuer den Maschinenhaendler'],a:1,e:'Zusaetzlich erkennt man ueber die Jahre Verbesserungspotenzial auf den einzelnen Parzellen.',s:'L46 / Abs. 6.2'},
{c:'saatbett',q:'Welche Angaben gehoeren zur Vorbereitung eines Parzellenblattes?',o:['Betriebsnummer, Betriebsname, Parzellenname und -flaeche, Hauptkultur und Sorte, Vorkultur','Nur die Flaeche','Nur der Duengerplan','Nur die Erntemenge'],a:0,e:'Fuer jede Parzelle wird ein eigenes Parzellenblatt vorbereitet.',s:'Abs. 6.1'},
{c:'saatbett',q:'Was schlagen Sie bei einer Hangparzelle mit 10 % Neigung, sandigem Boden und wiederholter Bodenabschwemmung vor?',o:['Mehr pfluegen','Erosionsanfaellige Kulturen reduzieren, mehr Kunstwiese und Gruenduengung, konservierende Verfahren, Bewirtschaftung laengs zum Hang','Tiefer pfluegen und talwaerts fahren','Nichts aendern'],a:1,e:'Zusaetzlich haeufiger gezogene Eggen statt Kreiselegge einsetzen.',s:'L49 Situation 1'},
{c:'saatbett',q:'Was schlagen Sie bei einer flachen Lehmboden-Parzelle mit starken Verdichtungen vor?',o:['Noch tiefer pfluegen','Evtl. Verzicht auf Rueben, konservierende Anbauverfahren, schonende Ernte mit Breitreifen und reduziertem Reifendruck, On-Land-Pflug','Mehr duengen','Mehr kalken'],a:1,e:'Rueben werden oft unter feuchten Bedingungen geerntet - das foerdert die Verdichtung.',s:'L49 Situation 2'}

];
